var Q12 = [
{n:1, q:'Delitos de homicidio y sus formas, es el epígrafe:', o:{a:'Del Título III del Libro I del Código Penal vigente.',b:'Del Título II del Libro II del Código Penal vigente.',c:'Del Título I del Libro II del Código Penal vigente.',d:'Del Título III del Libro II del Código Penal vigente.'}, correct:'c', why:{c:'Los delitos de homicidio y sus formas están en el Título I del Libro II del CP vigente.'}},
{n:2, q:'Los delitos de homicidio y sus formas se encuentran regulados en el Libro II del Código Penal, abarcando los artículos:', o:{a:'138 a 143 bis.',b:'138 a 143 ter.',c:'238 a 243 bis.',d:'238 a 243 ter.'}, correct:'a', why:{a:'Los delitos de homicidio y sus formas abarcan los artículos 138 a 143 bis del CP.'}},
{n:3, q:'De acuerdo con lo establecido en el art.138 del Código Penal, el que matare a otro será castigado, como reo de homicidio, con la pena de:', o:{a:'Prisión de 10 a 15 años.',b:'Prisión de 6 a 12 años.',c:'Prisión de 5 a 10 años.',d:'Prisión de 15 a 20 años.'}, correct:'a', why:{a:'El art.138 CP castiga el homicidio con prisión de 10 a 15 años.'}},
{n:4, q:'El delito de homicidio será castigado con la pena superior en grado:', o:{a:'a) Cuando concurra en su comisión alguna de las circunstancias del apartado 1 del artículo 140 del Código Penal.',b:'b) Cuando los hechos sean, además, constitutivos de un delito de atentado del artículo 550 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.138.2 CP prevé la pena superior en grado cuando concurren circunstancias del art.140 o los hechos constituyen atentado del art.550.'}},
{n:5, q:'El delito de homicidio será castigado con la pena superior en grado:', o:{a:'Cuando la víctima sea menor de 16 años o especialmente vulnerable.',b:'Cuando se trate de homicidio subsiguiente a un delito contra la libertad sexual en la misma víctima.',c:'Cuando el delito sea cometido por alguien perteneciente a un grupo u organización criminal.',d:'Cuando se produzca alguna de las circunstancia descritas en las respuestas anteriores.'}, correct:'d', why:{d:'El art.138.2 CP prevé pena superior en grado en todas esas circunstancias.'}},
{n:6, q:'El art.141 del Código Penal dispone que la provocación, la conspiración y la proposición para cometer el delito de homicidio se castiga con:', o:{a:'La mitad inferior de la pena señalada.',b:'La pena inferior en uno o dos grados',c:'La pena inferior en grado.',d:'La pena igual o inferior a la señalada para el autor/es, según los casos.'}, correct:'b', why:{b:'El art.141 CP establece que la provocación, conspiración y proposición para el homicidio se castigan con la pena inferior en uno o dos grados.'}},
{n:7, q:'Será castigado con la pena de prisión de quince a veinticinco años, como reo de asesinato...', o:{a:'El que matare a otro concurriendo alguna de las circunstancias tipificadas en el art.139 del Código Penal.',b:'El que matare a otro concurriendo más de una de las circunstancias tipificadas en el art.139 del Código Penal.',c:'El que matare a otro concurriendo alguna de las circunstancias tipificadas en el art.140 del Código Penal.',d:'El que matare a otro concurriendo más de una de las circunstancias tipificadas en el art.140 del Código Penal.'}, correct:'a', why:{a:'El art.139 CP castiga el asesinato con prisión de 15 a 25 años cuando concurre alguna de las circunstancias tipificadas.'}},
{n:8, q:'El delito de asesinato, previsto en el art.139 del Código Penal, es un delito:', o:{a:'Doloso.',b:'Imprudente.',c:'Leve.',d:'Flagrante.'}, correct:'a', why:{a:'El asesinato es siempre un delito doloso, no puede cometerse por imprudencia.'}},
{n:9, q:'Conforme establece el art.139 del Código Penal, existe delito de asesinato cuando se mata a otro:', o:{a:'Por quien perteneciere a un grupo u organización criminal.',b:'Con alevosía.',c:'De manera subsiguiente a un delito contra la libertad sexual que el autor hubiere cometido contra la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art.139.1.5ª CP incluye como circunstancia del asesinato matar de manera subsiguiente a un delito contra la libertad sexual. La opción a (pertenecer a grupo criminal) es circunstancia del art.140.1.2ª, no del art.139.'}},
{n:10, q:'Conforme establece el art.139 del Código Penal, existe delito de asesinato cuando se mata a otro:', o:{a:'Por precio, recompensa o promesa.',b:'Con ensañamiento, aumentando deliberada e inhumanamente el dolor del ofendido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.139 CP incluye como circunstancias del asesinato el precio/recompensa/promesa y el ensañamiento.'}},
{n:11, q:'Conforme establece el art.139 del Código Penal, existe delito de asesinato cuando se mata a otra persona:', o:{a:'Menor de doce años o incapaz.',b:'Para facilitar la comisión de otro delito o evitar que se descubra.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.139.1.4ª CP incluye como circunstancia del asesinato matar para facilitar la comisión de otro delito o evitar su descubrimiento.'}},
{n:12, q:'El art.141 del Código Penal dispone que la provocación, la conspiración y la proposición para cometer el delito de asesinato se castiga con:', o:{a:'La pena inferior en uno o dos grados',b:'Prisión permanente revisable.',c:'La pena inferior en grado.',d:'La pena igual o inferior a la señalada para el autor/es, según los casos.'}, correct:'a', why:{a:'El art.141 CP castiga la conspiración, proposición y provocación para el asesinato con la pena inferior en uno o dos grados.'}},
{n:13, q:'El hecho de que la víctima sea menor de dieciséis años de edad es una circunstancia que agrava el delito de ...', o:{a:'Lesiones del artículo 147.1.',b:'Homicidio.',c:'Asesinato.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'Que la víctima sea menor de 16 años es circunstancia que agrava el homicidio (art.138.2) y el asesinato (art.140).'}},
{n:14, q:'El hecho de que la víctima sea una persona especialmente vulnerable por razón de su edad es una circunstancia que agrava el delito de ...', o:{a:'Lesiones del artículo 147.1.',b:'Homicidio.',c:'Asesinato.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'La especial vulnerabilidad de la víctima agrava tanto el homicidio (art.138.2) como el asesinato (art.140).'}},
{n:15, q:'Cuando el hecho fuera subsiguiente a un delito contra la libertad sexual que el autor hubiera cometido sobre la víctima se impondrá la pena de prisión permanente revisable. Esta afirmación es aplicable al delito de:', o:{a:'Homicidio.',b:'Asesinato.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La prisión permanente revisable se aplica al asesinato cuando el hecho es subsiguiente a un delito contra la libertad sexual (art.140.1 CP).'}},
{n:16, q:'Cuando el delito se hubiera cometido por quien perteneciere a un grupo u organización criminal se impondrá la pena de prisión permanente revisable. Esta afirmación es aplicable al delito de:', o:{a:'Homicidio.',b:'Asesinato.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La prisión permanente revisable se aplica al asesinato cometido por miembro de grupo u organización criminal (art.140.1 CP).'}},
{n:17, q:'Cuando en la agresión se hubieren utilizado armas, instrumentos u objetos concretamente peligrosos para la vida o salud de la víctima se produce una agravación de la pena. Esta afirmación es aplicable al delito de:', o:{a:'Homicidio.',b:'Lesiones.',c:'Asesinato.',d:'Las respuestas a y b son correctas.'}, correct:'b', why:{b:'El uso de armas peligrosas es circunstancia agravante específica de las lesiones (art.148 CP), no del homicidio o asesinato.'}},
{n:18, q:'Cuando los hechos sean además constitutivos de un delito de atentado del artículo 550 del Código Penal, se agrava el delito de:', o:{a:'Homicidio.',b:'Asesinato.',c:'Lesiones.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El art.138.2 CP agrava el homicidio cuando los hechos son también constitutivos de atentado del art.550.'}},
{n:19, q:'Matar a una persona especialmente vulnerable por razón de su enfermedad o discapacidad, se castiga con la pena de:', o:{a:'Prisión permanente revisable.',b:'Prisión de 10 a 15 años.',c:'Prisión de 10 a 15 años en su mitad superior.',d:'La pena superior en grado a la de prisión de 10 a 15 años.'}, correct:'a', why:{a:'Matar a una persona especialmente vulnerable es asesinato agravado del art.140.1 CP, castigado con prisión permanente revisable.'}},
{n:20, q:'Matar con ensañamiento a una persona especialmente vulnerable por razón de su enfermedad o discapacidad, se castiga con la pena de:', o:{a:'Prisión permanente revisable.',b:'Prisión de 10 a 15 años.',c:'Prisión de 10 a 15 años en su mitad superior.',d:'La pena superior en grado a la de prisión de 10 a 15 años.'}, correct:'a', why:{a:'Concurrir más de una circunstancia del art.139 CP da lugar al art.140, castigado con prisión permanente revisable.'}},
{n:21, q:'Matar a una persona para facilitar la comisión de otro delito...', o:{a:'Constituye circunstancia agravante del delito de homicidio.',b:'Constituye circunstancia agravante del delito de asesinato.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Matar para facilitar otro delito es circunstancia del asesinato (art.139.1.4ª CP), no mera agravante del homicidio.'}},
{n:22, q:'Matar a una persona para evitar que se descubra la comisión de otro delito...', o:{a:'Constituye circunstancia agravante del delito de asesinato.',b:'Constituye delito de asesinato.',c:'Constituye agravante del delito de homicidio.',d:'Se castiga con la pena de prisión permanente revisable.'}, correct:'b', why:{b:'Matar para evitar el descubrimiento de otro delito constituye delito de asesinato (art.139.1.4ª CP).'}},
{n:23, q:'Cuando en un delito de asesinato concurra más de una de las circunstancias previstas en el artículo 139.1 del Código Penal:', o:{a:'Se impondrá la pena de prisión de quince a veinticinco años, en su mitad superior.',b:'Se impondrá la pena de prisión permanente revisable.',c:'Se impondrá la pena de prisión de quince a veinticinco años.',d:'Se impondrá la pena superior en un grado a la de prisión de quince a veinticinco años.'}, correct:'b', why:{b:'Cuando concurre más de una circunstancia del art.139.1, se aplica el art.140.1 CP: prisión permanente revisable.'}},
{n:24, q:'Cuando en un asesinato concurran más de una de las circunstancias previstas en el art.139.1 del Código Penal, se impondrá la pena de:', o:{a:'Prisión de 6 a 12 años.',b:'Prisión de 20 a 25 años.',c:'Prisión de 15 a 20 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Cuando concurre más de una circunstancia del art.139.1 se aplica prisión permanente revisable (art.140 CP), no ninguna de las penas indicadas.'}},
{n:25, q:'Se impondrá la pena de prisión permanente revisable con aplicación de lo dispuesto en el artículo 78 bis 1 y 2 del Código Penal:', o:{a:'Al reo de asesinato que hubiera sido condenado por la muerte de más de dos personas.',b:'Al reo de homicidio que hubiera sido condenado por la muerte de dos o más personas.',c:'Al reo de homicidio que hubiera sido condenado por la muerte de más de dos personas.',d:'Al reo de asesinato que hubiera sido condenado por la muerte de dos o más personas.'}, correct:'d', why:{d:'El art.140.2 CP establece prisión permanente revisable con art.78 bis para el reo de asesinato condenado por la muerte de dos o más personas.'}},
{n:26, q:'Conforme a lo previsto en el artículo140 bis del Código Penal, a los condenados por la comisión de uno o más delitos de homicidio o asesinato, se les podrá imponer además de las penas previstas en sus respectivos casos...', o:{a:'El internamiento en un centro educativo especial.',b:'Una medida de libertad vigilada.',c:'La privación del derecho a portar armas de 10 a 25 años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art.140 bis CP permite imponer libertad vigilada a los condenados por homicidio o asesinato.'}},
{n:27, q:'Conforme a lo previsto en el artículo140 bis del Código Penal, si la víctima y quien sea autor de los delitos de homicidio o asesinato tuvieran un hijo o hija en común, la autoridad judicial impondrá, respecto de este:', o:{a:'La pena de privación de la patria potestad.',b:'La obligación de garantizar la manutención.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'El art.140 bis CP establece que si hay hijo en común, la autoridad judicial impondrá la privación de la patria potestad.'}},
{n:28, q:'Según lo previsto en el art. 140 bis del Código Penal, si la víctima y quien sea autor de los delitos de homicidio o asesinato tuvieran un hijo o hija en común, la autoridad judicial impondrá, respecto de este, la pena de privación de la patria potestad:', o:{a:'Correcto, y se impondrá también una pena de libertad vigilada.',b:'Incorrecto.',c:'Correcto, y se impondrá la misma pena cuando la víctima fuere hijo o hija del autor, respecto de otros hijos e hijas, si existieren.',d:'Correcto, y se impondrán también una pena de libertad vigilada y la obligación de garantizar la manutención.'}, correct:'c', why:{c:'El art.140 bis CP también prevé la privación de la patria potestad respecto de otros hijos cuando la víctima fuera hijo o hija del autor.'}},
{n:29, q:'El art.142 del Código Penal castiga con la pena de prisión de 1 a 4 años:', o:{a:'Causar la muerte de otro dolosamente.',b:'Causar la muerte de otro por imprudencia grave.',c:'Causar la muerte de otro por imprudencia menos grave.',d:'Las respuestas b y c son correctas.'}, correct:'b', why:{b:'El art.142.1 CP castiga el homicidio por imprudencia grave con prisión de 1 a 4 años.'}},
{n:30, q:'En el art.142 del Código Penal se castiga el homicidio causado...', o:{a:'Dolosamente.',b:'Por imprudencia grave.',c:'Por imprudencia menos grave.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El art.142 CP castiga tanto el homicidio por imprudencia grave (art.142.1) como el causado por imprudencia menos grave (art.142.2).'}},
{n:31, q:'El homicidio causado por imprudencia leve se castiga...', o:{a:'Como delito leve del artículo 142. 3 del Código Penal.',b:'Como delito menos grave tipificado en el artículo 142.3 del Código Penal.',c:'Como grave infracción del artículo 35 de la Ley Orgánica 4/2015 de Protección de la Seguridad Ciudadana.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Tras la reforma LO 1/2015, no existe el homicidio por imprudencia leve en el CP. El art.142 solo recoge imprudencia grave y menos grave.'}},
{n:32, q:'Causar la muerte de una persona mediando imprudencia leve se castiga con la pena de:', o:{a:'Prisión de 1 a 4 años.',b:'Multa de 1 a 2 meses.',c:'Inhabilitación especial por un periodo de 3 a 6 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La imprudencia leve en homicidio no está tipificada como delito en el CP. No hay pena prevista.'}},
{n:33, q:'Si el delito se hubiera cometido utilizando vehículo a motor o ciclomotor, se podrá imponer la pena de privación del derecho a conducir vehículos a motor y ciclomotores..', o:{a:'Al que por imprudencia leve causare la muerte de otro.',b:'Al que por imprudencia menos grave causare la muerte de otro.',c:'Al que por imprudencia grave causare la muerte de otro.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El art.142 CP prevé la privación del derecho a conducir tanto para el homicidio por imprudencia grave como por imprudencia menos grave, si se usa vehículo.'}},
{n:34, q:'El art.142 del Código Penal castiga con la pena de prisión de 1 a 4 años al que por imprudencia grave causare la muerte de otro, y....', o:{a:'Si el homicidio imprudente se hubiera cometido utilizando un vehículo a motor o un ciclomotor, se impondrá asimismo la pena de privación del derecho a conducir vehículos a motor y ciclomotores de uno a seis años.',b:'Si el homicidio imprudente se hubiera cometido utilizando un arma de fuego, se impondrá también la pena de privación del derecho al porte o tenencia de armas por tiempo de uno a seis años.',c:'Si el homicidio se hubiera cometido por imprudencia profesional, se impondrá además la pena de inhabilitación especial para el ejercicio de la profesión, oficio o cargo por un periodo de tres a seis años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.142.1 CP prevé todas esas penas accesorias dependiendo del medio empleado o de si es imprudencia profesional.'}},
{n:35, q:'A los efectos de lo establecido en el art.142.1 del Código Penal, el delito de homicidio imprudente cometido utilizando un vehículo a motor o un ciclomotor...', o:{a:'Se reputará en todo caso como imprudencia grave la conducción en la que la concurrencia de alguna de las circunstancias previstas en el artículo 380 determinara la producción del hecho.',b:'Se reputará en todo caso como imprudencia grave la conducción en la que la concurrencia de alguna de las circunstancias previstas en el artículo 379 del CP determinara la producción del hecho.',c:'Se reputará en todo caso como imprudencia menos grave la conducción en la que la concurrencia de alguna de las circunstancias previstas en el artículo 380 determinara la producción del hecho.',d:'Se reputará en todo caso como imprudencia menos grave la conducción en la que la concurrencia de alguna de las circunstancias previstas en el artículo 379 determinara la producción del hecho.'}, correct:'b', why:{b:'El art.142.1 CP establece que se reputa imprudencia grave la conducción en que concurran circunstancias del art.379 (exceso de velocidad o tasas de alcohol).'}},
{n:36, q:'El homicidio causado por imprudencia profesional se castiga cuando concurre:', o:{a:'Imprudencia leve.',b:'Imprudencia menos grave.',c:'Imprudencia grave.',d:'Las respuestas b y c son correctas.'}, correct:'c', why:{c:'La imprudencia profesional en el homicidio se castiga solo cuando es imprudencia grave (art.142.1 CP).'}},
{n:37, q:'El que por imprudencia menos grave causare la muerte de otro, será castigado con la pena de:', o:{a:'Prisión de 6 a 18 meses.',b:'Multa de 3 a 18 meses.',c:'Prisión de 1 a 3 años.',d:'Multa de 12 a 24 meses.'}, correct:'b', why:{b:'El art.142.2 CP castiga el homicidio por imprudencia menos grave con multa de 3 a 18 meses.'}},
{n:38, q:'Si el delito se hubiera cometido utilizando un arma de fuego, se podrá imponer la pena de privación del derecho al porte o tenencia de armas por tiempo de 3 a 18 meses...', o:{a:'Al que por imprudencia leve causare la muerte de otro.',b:'Al que por imprudencia menos grave causare la muerte de otro.',c:'Al que por imprudencia grave causare la muerte de otro.',d:'Las respuestas b y c son correctas.'}, correct:'b', why:{b:'El art.142.2 CP prevé la privación del derecho a portar armas por 3 a 18 meses en el homicidio por imprudencia menos grave con arma de fuego.'}},
{n:39, q:'Respecto a la tipificación, en el art.142 del Código Penal, del delito de homicidio por imprudencia menos graves, indique la respuesta incorrecta:', o:{a:'Se reputará en todo caso como imprudencia menos grave aquella no calificada como grave en la que para la producción del hecho haya sido determinante la comisión de alguna de las infracciones graves de las normas de tráfico, circulación de vehículos a motor y seguridad vial.',b:'Si el homicidio se hubiera cometido utilizando un arma de fuego, se podrá imponer también la pena de privación del derecho al porte o tenencia de armas por tiempo de tres a dieciocho meses.',c:'Salvo en los casos en que se produzca utilizando un vehículo a motor o un ciclomotor, el delito podrá ser perseguible de oficio, mediante de denuncia de la persona agraviada o de su representante legal.',d:'La valoración sobre la existencia o no de la determinación del delito por la comisión de alguna de las infracciones graves de las normas de tráfico, circulación de vehículos a motor y seguridad vial deberá apreciarse en resolución motivada.'}, correct:'c', why:{c:'El homicidio por imprudencia menos grave cometido con vehículo solo es perseguible mediante denuncia; la opción c dice lo contrario, lo que es incorrecto.'}},
{n:40, q:'Salvo en los casos en que se produzca utilizando un vehículo a motor o un ciclomotor, solo será perseguible mediante denuncia de la persona agraviada o de su representante legal.', o:{a:'El delito de homicidio por imprudencia grave.',b:'El delito de homicidio por imprudencia menos grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El homicidio por imprudencia menos grave (sin vehículo) solo es perseguible mediante denuncia de la persona agraviada (art.142.2 CP).'}},
{n:41, q:'Según el art.142 bis) del Código Penal, en los casos de homicidio por imprudencia grave, el Juez o Tribunal podrá imponer motivadamente la pena superior en un grado, en la extensión que estime conveniente, si el hecho revistiere notoria gravedad...', o:{a:'En atención a la singular entidad y relevancia del riesgo creado y del deber normativo de cuidado infringido.',b:'Si hubiere provocado la muerte de dos o más personas.',c:'Si hubiere provocado la muerte de una persona y lesiones constitutivas de delito del artículo 152.1.2.º o 3.º del CP, en las demás.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.142 bis CP permite elevar la pena en todas esas circunstancias.'}},
{n:42, q:'Según el art.142 bis) del Código Penal, en los casos de homicidio por imprudencia grave, el Juez o Tribunal podrá imponer motivadamente la pena superior en dos grados, en la extensión que estime conveniente, si el hecho revistiere notoria gravedad...', o:{a:'En atención a los resultados gravosos producidos.',b:'Si el número de fallecidos fuere muy elevado.',c:'Si hubiere provocado la muerte de una persona y lesiones constitutivas de delito del artículo 152.1.2.º o 3.º del CP, en las demás.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.142 bis CP permite elevar hasta dos grados la pena en esas circunstancias de notoria gravedad.'}},
{n:43, q:'Andrés, que ha decidido matar a Fernando, lo espera agazapado detrás de unos matorrales y a su paso lo ataca por la espalda de manera sorpresiva con un cuchillo, causándole la muerte, sin que Fernando tenga oportunidad alguna de defenderse. De acuerdo con lo anterior, Andrés comete un delito de:', o:{a:'Asesinato.',b:'Homicidio doloso.',c:'Homicidio agravado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Andrés actúa con alevosía (ataque por sorpresa sin posibilidad de defensa), lo que califica el hecho como asesinato (art.139.1.1ª CP).'}},
{n:44, q:'Agustín, furioso porque Juan Carlos le debe dinero, contrata a Daniel para que torture y luego mate a Juan Carlos, ofreciéndole por ello la cantidad de 6.000 euros. Daniel lleva a cabo la tortura y muerte de Juan Carlos de acuerdo con el plan previsto. Teniendo en cuenta lo anterior, indique la respuesta correcta:', o:{a:'Daniel es autor de un delito de homicidio y Agustín es autor de un delito de asesinato.',b:'Daniel y Agustín son autores de un delito de asesinato.',c:'Daniel y Agustín son autores de un delito de homicidio.',d:'Daniel es autor de un delito de asesinato.'}, correct:'b', why:{b:'Tanto Daniel (ejecutor) como Agustín (inductor mediante precio) son autores de asesinato: Daniel por realizarlo con ensañamiento, Agustín por contratar mediante precio/recompensa.'}},
{n:45, q:'Blas y Fernando planean la muerte de Ignacio y deciden llevarla a cabo. La conversación es escuchada por un vecino que lo denuncia a la Policía. Partiendo de estos datos indique la respuesta correcta.', o:{a:'Blas y Fernando podrían ser condenados por un delito de conspiración para cometer un homicidio.',b:'Blas y Fernando podrían ser condenados por un delito de proposición para cometer un homicidio.',c:'Blas y Fernando podrían ser condenados por un delito de homicidio en grado de tentativa.',d:'No existe ningún tipo de responsabilidad para Blas ni para Fernando, dado que lo realizado son actos internos.'}, correct:'a', why:{a:'Dos personas que se conciertan para cometer un delito y deciden ejecutarlo cometen conspiración (art.17.1 CP), en este caso para el homicidio.'}},
{n:46, q:'El delito de inducción al suicidio se castiga en el Código Penal con la pena de:', o:{a:'Prisión de 2 a 5 años.',b:'Prisión de 4 a 8 años.',c:'Prisión de 6 a 10 años.',d:'La inducción al suicidio no es delito.'}, correct:'b', why:{b:'El art.143.1 CP castiga la inducción al suicidio con prisión de 4 a 8 años.'}},
{n:47, q:'El Código Penal castiga con pena de prisión de 6 a 10 años:', o:{a:'El hecho de cooperar con actos necesarios en el suicidio de otra persona.',b:'El hecho de cooperar con actos necesarios en el suicidio de otra persona, llegando hasta el punto de ejecutar la muerte.',c:'El hecho de causar o cooperar activamente con actos necesarios y directos en la muerte de otro, en aquellos casos en que la víctima sufriera una enfermedad grave que conduciría necesariamente a su muerte, o que le produjera padecimientos permanentes y difíciles de soportar.',d:'La inducción al suicidio de otra persona.'}, correct:'b', why:{b:'El art.143.3 CP castiga con prisión de 6 a 10 años la cooperación que llegue hasta el punto de ejecutar la muerte del que pide el suicidio. El art.143.4 (enfermo incurable con petición expresa) se castiga con penas INFERIORES en 1 o 2 grados.'}},
{n:48, q:'Cooperar con actos necesarios al suicidio de otra persona:', o:{a:'Se castiga con la pena de prisión de 2 a 5 años.',b:'Se castiga con la pena inferior en grado a la del delito de inducción al suicidio.',c:'Se castiga con la misma pena que el delito de inducción al suicidio.',d:'Se castiga con la pena de prisión de 6 a 10 años.'}, correct:'a', why:{a:'El art.143.2 CP castiga la cooperación necesaria al suicidio con prisión de 2 a 5 años.'}},
{n:49, q:'El que causare o cooperare activamente con actos necesarios y directos a la muerte de una persona que sufriera una enfermedad grave, crónica e imposibilitante o una enfermedad grave e incurable, con sufrimientos físicos o psíquicos constantes e insoportables, por la petición expresa, seria e inequívoca de esta, será castigado:', o:{a:'Con las penas señaladas en los números 2 y 3 del artículo 143 del Código Penal.',b:'Con las penas inferiores en un grado a las señaladas en los números 2 y 3 del artículo 143 del Código Penal.',c:'Con las penas inferiores en dos grados a las señaladas en los números 2 y 3 del artículo 143 del Código Penal.',d:'Con las penas inferiores en uno o dos grados a las señaladas en los apartados 2 y 3 del artículo 143 del Código Penal.'}, correct:'d', why:{d:'El art.143.4 CP establece que la eutanasia activa a petición del enfermo se castiga con las penas inferiores en uno o dos grados a las del art.143.2 y 143.3.'}},
{n:50, q:'De conformidad con lo establecido en el art.143.5 del Código penal, no incurrirá en responsabilidad penal quien causare o cooperare activamente a la muerte de otra persona:', o:{a:'Cumpliendo lo establecido en la ley orgánica reguladora de la eutanasia.',b:'Cumpliendo con el código deontológico del personal sanitario, en su caso.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'El art.143.5 CP exime de responsabilidad penal a quien actúa conforme a la Ley Orgánica reguladora de la eutanasia.'}},
{n:51, q:'El art.143 bis) del Código Penal castiga la distribución o difusión pública a través de Internet, del teléfono o de cualquier otra tecnología de la información o de la comunicación de contenidos específicamente destinados a promover, fomentar o incitar al suicidio de:', o:{a:'Personas menores de edad.',b:'Personas con discapacidad necesitadas de especial protección.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art.143 bis CP castiga la difusión de contenidos que inciten al suicidio de menores o personas con discapacidad.'}},
{n:52, q:'El delito tipificado en el art.143 bis) del Código Penal, consistente en promover, fomentar o incitar al suicidio de determinadas personas, se castiga:', o:{a:'Con la pena de prisión de uno a cinco años.',b:'Con la pena de prisión de uno a cuatro años.',c:'Con la pena de prisión de dos a cinco años.',d:'Con la pena de prisión de tres a cinco años.'}, correct:'b', why:{b:'El art.143 bis CP castiga la incitación al suicidio de menores o personas con discapacidad con prisión de 1 a 4 años.'}},
{n:53, q:'Las autoridades judiciales ordenarán la adopción de las medidas necesarias para la retirada de los contenidos a los que se refiere el art.143 bis del Código Penal (sobre inducción al suicidio), para la interrupción de los servicios que ofrezcan predominantemente dichos contenidos o para el bloqueo de unos y otros:', o:{a:'Cuando radiquen en el extranjero.',b:'Cuando radiquen en países que no sean de la Unión Europea, pero que tengan Tratados con España.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'a', why:{a:'El art.143 bis CP permite ordenar la retirada o bloqueo de contenidos cuando radiquen en el extranjero.'}},
{n:54, q:'El que, por cualquier medio o procedimiento, causare a otro una lesión que menoscabe su integridad corporal o su salud física o mental, será castigado:', o:{a:'Como reo del delito de lesiones con la pena de prisión de 3 meses a 2 años o multa de 6 a 12 meses.',b:'Como reo del delito de lesiones con la pena de prisión de 3 meses a 3 años o multa de 6 a 12 meses.',c:'Como reo del delito de lesiones con la pena de prisión de 3 meses a 3 años o multa de 6 a 18 meses.',d:'Como reo del delito de lesiones con la pena de prisión de 6 meses a 5 años o multa de 6 a 18 meses.'}, correct:'b', why:{b:'El art.147.1 CP castiga las lesiones con prisión de 3 meses a 3 años o multa de 6 a 12 meses.'}},
{n:55, q:'Para que las lesiones del artículo 147.1 del Código Penal sean constitutivas de delito, es necesario:', o:{a:'Que requieran objetivamente para su sanidad, además de una primera asistencia facultativa, tratamiento médico o quirúrgico.',b:'Que hubiere mediado ensañamiento',c:'Que hayan sido causadas con medios o instrumentos peligrosos para la vida o la integridad de las personas.',d:'Que la víctima fuere menor de 12 años o incapaz.'}, correct:'a', why:{a:'El art.147.1 CP exige para el delito de lesiones que la lesión requiera tratamiento médico o quirúrgico además de la primera asistencia.'}},
{n:56, q:'El delito de lesiones del art.147.1.del Código Penal se castiga:', o:{a:'Con la pena de prisión de 3 meses a 3 años y multa de 6 a 12 meses.',b:'Con la pena de prisión de 3 meses a 3 años o multa de 6 a 12 meses.',c:'Con la pena de prisión de 2 a 5 años y multa de 6 a 12 meses.',d:'Con la pena de prisión de 2 a 5 años o multa de 6 a 12 meses.'}, correct:'b', why:{b:'El art.147.1 CP castiga las lesiones con prisión de 3 meses a 3 años O multa de 6 a 12 meses (no ambas conjuntamente).'}},
{n:57, q:'Según lo establecido en el art.147.1. del Código Penal...', o:{a:'La simple vigilancia o seguimiento facultativo del curso de la lesión no se considerará tratamiento médico.',b:'Causar a otro una mutilación genital será castigado con prisión de 2 a 5 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.147.1 CP establece expresamente que la simple vigilancia del curso de la lesión no se considera tratamiento médico.'}},
{n:58, q:'Las lesiones del art.147.1.del Código Penal, serán castigadas con prisión de 2 a 5 años, atendiendo al resultado causado o riesgo producido:', o:{a:'Cuando en la agresión se hubieren utilizado armas, instrumentos, objeto, medios métodos o formas concretamente peligrosos para la vida o la salud física o psíquica del lesionado.',b:'Cuando además de una primera asistencia facultativa, necesiten tratamiento médico o quirúrgico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.148.1 CP agrava las lesiones a prisión de 2 a 5 años cuando se usan medios concretamente peligrosos para la vida o salud.'}},
{n:59, q:'Las lesiones del art.147.1.del Código Penal, serán castigadas con prisión de 2 a 5 años, atendiendo al resultado causado o riesgo producido:', o:{a:'Cuando hubiere mediado alevosía.',b:'Cuando la víctima fuere menor de 14 años o persona con discapacidad necesitada de especial protección.',c:'Si la víctima fuese una persona especialmente vulnerable que conviva con el autor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.148 CP agrava las lesiones en todos esos supuestos.'}},
{n:60, q:'Las lesiones del art.147.1.del Código Penal, serán castigadas con prisión de 2 a 5 años, atendiendo al resultado causado o riesgo producido:', o:{a:'Si en la agresión hubiere mediado ensañamiento.',b:'Si la víctima o hubiere estado ligada al autor por una análoga relación de afectividad a la del matrimonio, aún sin convivencia.',c:'Si la víctima fuere o hubiere sido esposa del autor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.148 CP prevé agravación en todos esos casos.'}},
{n:61, q:'Las lesiones tipificadas en el art. 149.1 del Código Penal, se castigan con pena de:', o:{a:'Prisión de 6 a 10 años y multa de 12 a 24 meses.',b:'Prisión de 6 a 10 años y multa de 12 a 18 meses.',c:'Prisión de 6 a 12 años y multa de 12 a 24 meses.',d:'Prisión de 6 a 12 años.'}, correct:'d', why:{d:'El art.149.1 CP castiga las lesiones graves (pérdida de órgano principal, sentido, impotencia, esterilidad, grave deformidad) con prisión de 6 a 12 años.'}},
{n:62, q:'En el art.149.1 del Código Penal se castiga a quien, por cualquier medio o procedimiento, causara a otro:', o:{a:'La pérdida o inutilidad de un órgano o miembro principal.',b:'Una deformidad no grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.149.1 CP castiga la pérdida o inutilidad de órgano o miembro principal, no la deformidad no grave.'}},
{n:63, q:'En el art.149.1 del Código Penal se castiga a quien, por cualquier medio o procedimiento, causara a otro:', o:{a:'La pérdida o inutilidad de un órgano o miembro no principal.',b:'Una grave deformidad.',c:'La impotencia.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El art.149.1 CP castiga causar grave deformidad o impotencia.'}},
{n:64, q:'En el art.149.1 del Código Penal se castiga a quien, por cualquier medio o procedimiento, causara a otro:', o:{a:'Una grave enfermedad somática o psíquica.',b:'La esterilidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.149.1 CP castiga tanto causar grave enfermedad somática o psíquica como la esterilidad.'}},
{n:65, q:'En el art.149.1 del Código Penal se castiga a quien, por cualquier medio o procedimiento, causara a otro:', o:{a:'La pérdida o inutilidad de un órgano o miembro no principal.',b:'La pérdida de un sentido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.149.1 CP castiga la pérdida de un sentido, junto a otras lesiones graves.'}},
{n:66, q:'Causar a otro una mutilación genital en cualquiera de sus manifestaciones:', o:{a:'Está tipificado como delito en el artículo 147.2 del Código Penal.',b:'Se castiga con la pena de prisión de 6 a 12 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La mutilación genital se castiga con prisión de 6 a 12 años según el art.149.2 CP.'}},
{n:67, q:'Cuando la víctima de un delito de mutilación genital fuere menor o incapaz...', o:{a:'Se impondrán las penas previstas en su mitad superior.',b:'El autor podrá ser castigado con la pena de inhabilitación especial para el ejercicio de la patria potestad por un tiempo de 4 a 10 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.149.2 CP prevé ambas consecuencias cuando la víctima de mutilación genital es menor o incapaz.'}},
{n:68, q:'El delito de lesiones tipificado en el artículo 147.2 del Código Penal...', o:{a:'Se castiga con la pena de multa de uno a tres meses.',b:'Solo es perseguible mediante denuncia de la persona agraviada o de su representante legal.',c:'Se castiga con la pena de multa de 3 a 18 meses.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'El art.147.2 CP castiga las lesiones leves (que no requieren tratamiento médico) con multa de 1 a 3 meses, y son perseguibles solo mediante denuncia.'}},
{n:69, q:'El art.147.3 del Código Penal establece que el que golpeare o maltratare de obra a otro sin causarle lesión, será castigado:', o:{a:'Con la pena de multa de uno a dos meses.',b:'Con la pena de prisión de uno a dos meses.',c:'Con la pena de multa de tres a cinco meses.',d:'Con la pena de prisión de tres a cinco meses.'}, correct:'a', why:{a:'El art.147.3 CP castiga el maltrato de obra sin lesión con multa de 1 a 2 meses.'}},
{n:70, q:'Solo son perseguibles mediante denuncia de la persona agraviada o de su representante legal:', o:{a:'Los delitos de lesiones tipificados en los artículos 147.1 y 147.2 del Código Penal.',b:'Los delitos de lesiones tipificados en los artículos 147.1 y 147.3 del Código Penal.',c:'Los delitos de lesiones tipificados en los artículos 147.2 y 147.3 del Código Penal.',d:'Los delitos de lesiones tipificados en los artículos 147.3 y 147.4 del Código Penal.'}, correct:'c', why:{c:'Solo los delitos del art.147.2 (lesiones leves) y 147.3 (maltrato sin lesión) son perseguibles mediante denuncia.'}},
{n:71, q:'Los delitos de lesiones tipificados en el artículo 150 del Código Penal...', o:{a:'Se castigan con la pena de prisión de 3 a 6 años.',b:'Se castigan con las penas inferiores en grado a las previstas en el artículo 149 de éste Código.',c:'Se castigan con las penas inferiores en uno o dos grados a las previstas en el artículo 149 de éste Código.',d:'Se castigan con las penas de prisión de 3 a 6 años y multa de 1 a 3 meses.'}, correct:'a', why:{a:'El art.150 CP castiga la pérdida o inutilidad de órgano no principal o deformidad con prisión de 3 a 6 años.'}},
{n:72, q:'La proposición, conspiración y provocación para cometer cualquiera de los delitos de lesiones previstos en los artículos 147 al 150 del Código Penal se castiga:', o:{a:'Con las penas inferiores en grado a las respectivamente previstas en cada caso.',b:'Con las penas respectivamente previstas para cada delito, en su mitad inferior.',c:'Con las penas inferiores en uno o dos grados a las respectivamente previstas.',d:'En los delitos de lesiones no se castigan los actos preparatorios.'}, correct:'a', why:{a:'Los actos preparatorios de los delitos de lesiones se castigan con penas inferiores en grado a las previstas (art.151 CP).'}},
{n:73, q:'En función del riesgo creado y del resultado producido, la causación por imprudencia grave de alguna de las lesiones previstas en el artículo 147.1 del Código Penal:', o:{a:'Se castiga con prisión de 3 a 6 meses o multa de 6 a 18 meses.',b:'Se castiga con prisión de 3 a 6 meses y multa de 6 a 18 meses.',c:'Se castiga con prisión de 3 a 5 meses o multa de 6 a 12 meses.',d:'Se castiga con prisión de 3 a 5 meses y multa de 6 a 12 meses.'}, correct:'a', why:{a:'El art.152.1.1ª CP castiga las lesiones del art.147.1 por imprudencia grave con prisión de 3 a 6 meses o multa de 6 a 18 meses.'}},
{n:74, q:'En función del riesgo creado y del resultado producido, la causación por imprudencia grave de alguna de las lesiones previstas en el artículo 149 del Código Penal:', o:{a:'Se castiga con prisión de 6 a 18 meses.',b:'Se castiga con prisión de 1 a 3 años.',c:'Se castiga con multa de 3 a 12 meses.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art.152.1.2ª CP castiga las lesiones del art.149 por imprudencia grave con prisión de 1 a 3 años.'}},
{n:75, q:'En función del riesgo creado y del resultado producido, la causación por imprudencia grave de alguna de las lesiones previstas en el artículo 150 del Código Penal:', o:{a:'Se castiga con prisión de 6 meses a 2 años.',b:'Se castiga con prisión de 1 a 3 años.',c:'Se castiga con multa de 3 a 12 meses.',d:'Se castiga con multa de 3 a 18 meses.'}, correct:'d', why:{d:'El art.152.1.3ª CP castiga las lesiones del art.150 por imprudencia grave con multa de 3 a 18 meses.'}},
{n:76, q:'Cuando por imprudencia grave, y utilizando un vehículo a motor o ciclomotor, se causaren lesiones tipificadas en los artículos 147.1, 149 y 150 del Código Penal, además de la pena respectivamente prevista para cada caso...', o:{a:'Se podrá imponer también la de privación del derecho a conducir vehículos a motor y ciclomotores de 3 meses a 1 año.',b:'Se podrá imponer también la de privación del derecho a conducir vehículos a motor y ciclomotores de 1 a 4 años.',c:'Se impondrá asimismo la de privación del derecho a conducir vehículos a motor y ciclomotores de 3 meses a 1 año.',d:'Se impondrá asimismo la de privación del derecho a conducir vehículos a motor y ciclomotores de 1 a 4 años.'}, correct:'d', why:{d:'El art.152.2 CP establece que se impondrá también la privación del derecho a conducir de 1 a 4 años en lesiones por imprudencia grave con vehículo.'}},
{n:77, q:'Cuando por imprudencia grave, y utilizando un arma de fuego, se causaren lesiones tipificadas en los artículos 147.1, 149 y 150 del Código Penal, además de la pena respectivamente prevista para cada caso...', o:{a:'Se podrá imponer también la de privación del derecho a la tenencia o porte de armas de 3 meses a 1 año.',b:'Se podrá imponer también la de privación del derecho a la tenencia o porte de armas de 1 a 4 años.',c:'Se impondrá también la de privación del derecho a la tenencia o porte de armas de 3 meses a 1 año.',d:'Se impondrá también la de privación del derecho a la tenencia o porte de armas de 1 a 4 años.'}, correct:'d', why:{d:'El art.152.2 CP establece la privación del derecho a tenencia de armas de 1 a 4 años en lesiones por imprudencia grave con arma de fuego.'}},
{n:78, q:'En el artículo 152 del Código Penal se castigan las lesiones previstas en los artículos 147.1, 149 y 150 de este Código, cometidas por imprudencia profesional, siempre que dicha imprudencia hubiere sido:', o:{a:'Grave.',b:'Menos grave.',c:'Leve.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'La imprudencia profesional en lesiones se castiga solo cuando es imprudencia grave (art.152.1 CP).'}},
{n:79, q:'Si las lesiones de los artículos 147.1, 149 y 150 del CP hubieran sido cometidas por imprudencia profesional grave, se impondrá, además de la pena principal, la pena de inhabilitación especial para el ejercicio de la profesión, oficio o cargo:', o:{a:'Por un período de doce meses a tres años.',b:'Por un período de seis meses a cuatro años.',c:'Por un período de dieciocho meses a cinco años.',d:'Por un período de doce meses a cuatro años.'}, correct:'b', why:{b:'El art.152.1 CP prevé inhabilitación especial de 6 meses a 4 años para imprudencia profesional grave en lesiones.'}},
{n:80, q:'El que por imprudencia menos grave causare alguna de las lesiones a que se refiere el artículo 147.1 del Código Penal, será castigado:', o:{a:'Con la pena de multa de uno a tres meses.',b:'Con la pena de multa de uno a dos meses.',c:'Con la pena de multa de dos a cuatro meses.',d:'Con la pena de multa de tres a cinco meses.'}, correct:'b', why:{b:'El art.152.2 CP castiga las lesiones del art.147.1 por imprudencia menos grave con multa de 1 a 2 meses.'}},
{n:81, q:'El que por imprudencia menos grave causare alguna de las lesiones a que se refieren los artículos 149 y 150 del Código Penal, será castigado:', o:{a:'Con la pena de multa de uno a tres meses.',b:'Con la pena de multa de uno a dos meses.',c:'Con la pena de multa de dos a cuatro meses.',d:'Con la pena de multa de tres a doce meses.'}, correct:'d', why:{d:'El art.152.2 CP castiga las lesiones de los arts.149 y 150 por imprudencia menos grave con multa de 3 a 12 meses.'}},
{n:82, q:'Cuando por imprudencia menos grave, y utilizando un vehículo a motor o ciclomotor, se causaren lesiones tipificadas en los artículos 147.1, 149 y 150 del Código Penal, además de la pena respectivamente prevista para cada caso...', o:{a:'Se podrá imponer también la de privación del derecho a conducir vehículos a motor y ciclomotores de 3 meses a 1 año.',b:'Se podrá imponer también la de privación del derecho a conducir vehículos a motor y ciclomotores de 1 a 4 años.',c:'Se impondrá también la de privación del derecho a conducir vehículos a motor y ciclomotores de 3 a 18 meses.',d:'Se impondrá asimismo la de privación del derecho a conducir vehículos a motor y ciclomotores de 1 a 4 años.'}, correct:'a', why:{a:'El art.152.2 CP prevé que en imprudencia menos grave con vehículo, SE PODRÁ (no se impondrá obligatoriamente) la privación del derecho a conducir de 3 meses a 1 año.'}},
{n:83, q:'Cuando por imprudencia menos grave, y utilizando un arma de fuego, se causaren lesiones tipificadas en los artículos 147.1, 149 y 150 del Código Penal, además de la pena respectivamente prevista para cada caso...', o:{a:'Se podrá imponer también la de privación del derecho a la tenencia o porte de armas de 3 meses a 1 año.',b:'Se podrá imponer también la de privación del derecho a la tenencia o porte de armas de 1 a 4 años.',c:'Se impondrá también la de privación del derecho a la tenencia o porte de armas de 3 meses a 1 año.',d:'Se impondrá también la de privación del derecho a la tenencia o porte de armas de 1 a 4 años.'}, correct:'a', why:{a:'En imprudencia menos grave con arma de fuego, el art.152.2 CP prevé que SE PODRÁ imponer la privación del derecho a portar armas de 3 meses a 1 año.'}},
{n:84, q:'Solo es perseguible mediante denuncia de la persona agraviada o de su representante legal, el delito de lesiones por imprudencia menos grave en...', o:{a:'El artículo 147.1 del Código Penal.',b:'El artículo 152.1 del Código Penal.',c:'El artículo 152.2 del Código Penal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El delito de lesiones por imprudencia menos grave del art.152.2 CP solo es perseguible mediante denuncia del agraviado.'}},
{n:85, q:'Causar alguna de las lesiones previstas en el artículo 147.1 del Código Penal por imprudencia leve:', o:{a:'Se castiga con la pena de multa de uno a dos meses.',b:'Constituye infracción a la Ley Orgánica 4/2015 de Protección de la Seguridad Ciudadana.',c:'Es un delito leve.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'d', why:{d:'Las lesiones por imprudencia leve no están tipificadas como delito en el CP tras la reforma de 2015.'}},
{n:86, q:'En los casos de lesiones por imprudencia grave, el Juez o Tribunal podrá imponer motivadamente la pena superior en un grado, en la extensión que estime conveniente, si el hecho revistiere notoria gravedad, en atención a la singular entidad y relevancia del riesgo creado y del deber normativo de cuidado infringido...', o:{a:'Si hubiere provocado lesiones constitutivas de delito del artículo 152.1.2.º del CP, a una pluralidad de personas.',b:'Si hubiere provocado lesiones constitutivas de delito del artículo 152.1.3.º del CP, a una pluralidad de personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.152 bis CP permite elevar la pena en un grado cuando se causen lesiones graves a pluralidad de personas.'}},
{n:87, q:'En los casos de lesiones por imprudencia grave, el Juez o Tribunal podrá imponer motivadamente la pena superior en dos grados, en la extensión que estime conveniente, si el hecho revistiere notoria gravedad, en atención a la singular entidad y relevancia del riesgo creado y del deber normativo de cuidado infringido...', o:{a:'Si hubiere provocado lesiones constitutivas de delito del artículo 152.1.2.º o 3.º del CP y el número de lesionados fuere muy elevado.',b:'Si hubiere provocado lesiones constitutivas de delito del artículo 153.1.2.º o 3.º del CP, a una pluralidad de personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.152 bis CP permite elevar dos grados cuando se causen lesiones graves y el número de lesionados sea muy elevado.'}},
{n:88, q:'En el artículo 153.1 del Código Penal se castiga al que, por cualquier medio o procedimiento, causare a otro menoscabo psíquico o una lesión de menor gravedad de las previstas en el artículo 147.2 de este Código, siempre que:', o:{a:'La ofendida sea o haya sido esposa o mujer que esté o haya estado ligada a él por análoga relación de afectividad aun sin convivencia.',b:'El ofendido sea ascendiente o descendiente del agresor.',c:'El ofendido sea hermano del agresor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.153.1 CP castiga el menoscabo psíquico o lesión leve cuando la víctima es la esposa/pareja, o ascendiente, descendiente o hermano del agresor.'}},
{n:89, q:'En el artículo 153.1 del Código Penal se castiga al que, por cualquier medio o procedimiento, maltratare de obra a otro sin causarle lesión, siempre que:', o:{a:'La ofendida sea o haya sido esposa o mujer que esté o haya estado ligada a él por análoga relación de afectividad aun sin convivencia.',b:'La persona especialmente vulnerable que conviva con el autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.153.1 CP se aplica al maltrato sin lesión cuando la víctima es la pareja o expareja del autor.'}},
{n:90, q:'El delito de lesiones a la esposa o mujer ligada al autor por análoga relación de afectividad, tipificado en el artículo 153.1 del Código Penal, se castiga con:', o:{a:'Prisión de 6 meses a 2 años, o trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 a 3 años.',b:'Prisión de 6 meses a 1 año, o trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 año y un día a 3 años.',c:'Prisión de 6 meses a 2 años y trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 a 3 años.',d:'Prisión de 6 meses a 1 año y trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 año y un día a 3 años.'}, correct:'b', why:{b:'El art.153.1 CP castiga con prisión de 6 meses a 1 año O trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a portar armas de 1 año y 1 día a 3 años.'}},
{n:91, q:'El delito de lesiones a la esposa o mujer ligada al autor por análoga relación de afectividad, tipificado en el artículo 153.1 del Código Penal, podrá ser castigado con la pena de inhabilitación para el ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento:', o:{a:'Cuando hubiere mediado ensañamiento.',b:'Cuando el juez o tribunal lo estime adecuado al interés del menor o persona con discapacidad necesitada de especial protección.',c:'Si el autor hubiese hecho uso de armas u otros objetos igualmente peligrosos para la vida o integridad física del ofendido.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La inhabilitación para ejercer la patria potestad en el art.153.1 CP puede imponerse en todos esos supuestos.'}},
{n:92, q:'Comete delito del artículo 153.2 del Código Penal el que, por cualquier medio o procedimiento, causare a otro menoscabo psíquico o una lesión de menor gravedad de las previstas en el artículo 147.2 de éste Código, siempre que la víctima sea:', o:{a:'Esposa o persona ligada al autor por análoga relación de afectividad, aún sin convivencia.',b:'Ascendiente, descendiente o hermano del autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.153.2 CP se aplica cuando la víctima es ascendiente, descendiente o hermano del autor (no la pareja, que va en el art.153.1).'}},
{n:93, q:'Cuando los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal se perpetren en presencia de menores, la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art.153.3 CP agrava la pena a su mitad superior cuando los hechos se cometen en presencia de menores.'}},
{n:94, q:'Cuando en los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal se utilicen armas la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El uso de armas en los delitos del art.153 agrava la pena a su mitad superior (art.153.3 CP).'}},
{n:95, q:'Cuando los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal tengan lugar en el domicilio común o en el de la víctima, la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Cometer los hechos del art.153 en el domicilio común o de la víctima agrava la pena a su mitad superior (art.153.3 CP).'}},
{n:96, q:'Cuando los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal se realicen quebrantando una pena de las previstas en el artículo 48 de éste Código, o una medida cautelar o de seguridad de la misma naturaleza, la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El quebrantamiento de medidas del art.48 CP en el contexto del art.153 agrava la pena a su mitad superior.'}},
{n:97, q:'Respecto a los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal, indique la respuesta correcta:', o:{a:'Pueden ser castigados con las respectivas penas en su mitad inferior, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a las circunstancias personales del autor y las concurrentes en la realización del hecho.',b:'Pueden ser castigados con la pena inferior en grado, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a las circunstancias personales del autor y las concurrentes en la realización del hecho.',c:'Pueden ser castigados con las respectivas penas en su mitad inferior, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a los medios utilizados y al resultado producido.',d:'Pueden ser castigados con la pena inferior en grado, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a los medios utilizados y al resultado producido.'}, correct:'b', why:{b:'El art.153.4 CP permite imponer la pena inferior en grado cuando el juez lo razone atendiendo a las circunstancias personales del autor.'}},
{n:98, q:'Respecto al delito de participación en riña tumultuaria del artículo 154 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga la utilización de medios o instrumentos que pongan en peligro la vida o integridad física de las personas.',b:'Para que exista delito, los sujetos activos deben estar riñendo entre sí, acometiéndose tumultuariamente.',c:'No existe delito cuando ninguno de los implicados en la riña sufre lesiones.',d:'La pena a imponer por este delito es la prisión de 3 meses a 1 año, o multa de 6 a 24 meses.'}, correct:'c', why:{c:'La existencia del delito de riña tumultuaria no requiere que haya lesionados; basta la utilización de medios peligrosos (art.154 CP).'}},
{n:99, q:'En los delitos de lesiones, el consentimiento válido, libre, espontáneo y expresamente emitido por el ofendido:', o:{a:'Permite imponer la pena en su mitad inferior.',b:'Obliga a imponer la pena inferior en grado.',c:'Permite imponer la pena inferior en uno o dos grados.',d:'Obliga a imponer la pena inferior en uno o dos grados.'}, correct:'c', why:{c:'El art.155 CP establece que el consentimiento válido del ofendido en lesiones permite imponer la pena inferior en uno o dos grados.'}},
{n:100, q:'En los delitos de lesiones no será válido el consentimiento otorgado por:', o:{a:'Menores de edad.',b:'Personas con discapacidad necesitadas de especial protección.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.155 CP establece que el consentimiento no es válido cuando lo otorgan menores de edad o personas con discapacidad.'}},
{n:101, q:'De acuerdo con lo previsto en el art.156 del Código Penal, el consentimiento válido, libre, consciente y expresamente emitido, exime de responsabilidad penal:', o:{a:'En las lesiones producidas entre personas de una misma familia o que convivan juntos.',b:'Cuando se trate de lesiones leves e imprudentes.',c:'En los supuestos de trasplantes de órganos, efectuados con arreglo a la ley.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art.156 CP establece que el consentimiento exime de responsabilidad penal en los trasplantes de órganos conforme a la ley, cirugías transexuales y esterilizaciones.'}},
{n:102, q:'De acuerdo con lo previsto en el art.156 del Código Penal, el consentimiento válido, libre, consciente y expresamente emitido, exime de responsabilidad criminal:', o:{a:'En las esterilizaciones realizadas por facultativo.',b:'En la cirugía transexual realizada por facultativo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.156 CP exime de responsabilidad en esterilizaciones y cirugía transexual realizadas por facultativo con consentimiento del interesado.'}},
{n:103, q:'No es válido el consentimiento emitido en los supuestos de trasplante de órganos, esterilizaciones y cirugía transexual...', o:{a:'Que se haya obtenido viciadamente.',b:'Que se haya obtenido mediante precio, recompensa o promesa.',c:'Cuando el otorgante sea menor de edad o carezca absolutamente de aptitud para prestarlo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.156 CP invalida el consentimiento obtenido viciadamente, mediante precio o cuando el otorgante sea menor o carezca de aptitud.'}},
{n:104, q:'Promover, favorecer, facilitar, publicar o ejecutar el tráfico de órganos humanos se castiga en el artículo 156 bis del Código Penal, con las penas de:', o:{a:'Prisión de 4 a 8 años, si se trata de órgano de persona viva, y prisión de 3 a 6 años, cuando se trate de órgano de persona fallecida.',b:'Prisión de 6 a 12 años, si se trata de órgano de persona viva, y prisión de 3 a 6 años, cuando se trate de órgano de persona fallecida.',c:'Prisión de 4 a 8 años, si se trata de órgano principal, y prisión de 6 meses a 3 años, cuando se trate de órgano no principal.',d:'Prisión de 6 a 12 años, si se trata de órgano principal, y prisión de 6 meses a 3 años, cuando se trate de órgano no principal.'}, correct:'a', why:{a:'El art.156 bis CP castiga el tráfico de órganos con prisión de 4 a 8 años (persona viva) o 3 a 6 años (persona fallecida).'}},
{n:105, q:'Según establece el art.156 bis) del Código Penal, se entenderá por tráfico de órganos humanos:', o:{a:'La extracción u obtención ilícita de órganos humanos ajenos.',b:'La preparación, preservación, almacenamiento, transporte, traslado, recepción, importación o exportación de órganos ilícitamente extraídos.',c:'El uso de órganos ilícitamente extraídos con la finalidad de su trasplante o para otros fines.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.156 bis CP define el tráfico de órganos incluyendo la extracción, preparación/almacenamiento y uso ilícito de órganos.'}},
{n:106, q:'Según establece el art.156 bis) del Código Penal, la extracción u obtención de órganos humanos será ilícita:', o:{a:'Cuando se haya realizado sin el consentimiento libre, informado y expreso del donante vivo en la forma y con los requisitos previstos legalmente.',b:'Cuando se haya realizado sin la necesaria autorización exigida por la ley en el caso del donante fallecido.',c:'Cuando, a cambio de la extracción u obtención, en provecho propio o ajeno, se solicitare o recibiere por el donante o un tercero, por sí o por persona interpuesta, dádiva o retribución de cualquier clase o se aceptare ofrecimiento o promesa.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.156 bis CP establece que la extracción es ilícita en todos esos supuestos.'}},
{n:107, q:'Según lo establecido en el art.156 bis del Código Penal, respecto al tráfico de órganos humanos:', o:{a:'No se entenderá por dádiva o retribución el resarcimiento de los gastos o pérdida de ingresos derivados de la donación.',b:'La extracción de un órgano será lícita aun cuando se haya realizado sin la autorización previa en el caso del donante fallecido.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.156 bis CP establece expresamente que el resarcimiento de gastos de la donación no se considera dádiva o retribución.'}},
{n:108, q:'El art.156.2. bis) del Código Penal castiga a las que, en provecho propio o ajeno:', o:{a:'Solicitaren o recibieren, por sí o por persona interpuesta, dádiva o retribución de cualquier clase, o aceptaren ofrecimiento o promesa para proponer o captar a un donante o a un receptor de órganos;',b:'Ofrecieren o entregaren, por sí o por persona interpuesta, dádiva o retribución de cualquier clase a un personal facultativo, funcionario público o particular con ocasión del ejercicio de su profesión o cargo en clínicas, establecimientos o consultorios, públicos o privados, con el fin de que se lleve a cabo o se facilite la extracción u obtención ilícitas o la implantación de órganos ilícitamente extraídos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.156 bis 2 CP castiga tanto solicitar dádivas para captar donantes como ofrecerlas al personal sanitario para facilitar extracciones ilícitas.'}},
{n:109, q:'Si el receptor de un órgano consintiere la realización del trasplante conociendo su origen ilícito, será castigado', o:{a:'Con las penas respectivamente previstas para el delito de tráfico ilegal de órganos humanos ajenos.',b:'Con las penas respectivamente previstas para el delito de tráfico ilegal de órganos humanos ajenos, en su mitad superior.',c:'Con las penas respectivamente previstas para el delito de tráfico ilegal de órganos humanos ajenos, en su mitad inferior.',d:'Con las mismas penas previstas para el delito tipificado en el art.156 bis del CP, que podrán rebajarse en uno o dos grados, atendiendo a las circunstancias del hecho y del culpable.'}, correct:'c', why:{c:'El receptor que consiente conociendo el origen ilícito se castiga con las penas del tráfico de órganos en su mitad inferior (art.156 bis 3 CP).'}},
{n:110, q:'Promover, favorecer, facilitar, publicar o ejecutar el tráfico de órganos humanos se castigará con las penas superiores en grado:', o:{a:'Cuando se hubiera puesto en grave peligro la vida o la integridad física o psíquica de la víctima del delito.',b:'Cuando la víctima sea menor de edad o especialmente vulnerable por razón de su edad, discapacidad, enfermedad o situación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.156 bis 4 CP agrava las penas en ambos supuestos: peligro para la vida y víctima especialmente vulnerable.'}},
{n:111, q:'Promover, favorecer, facilitar, publicar o ejecutar el tráfico de órganos humanos se castigará con las penas superiores en grado, en su mitad superior:', o:{a:'Cuando se hubiera puesto en grave peligro la vida o la integridad física o psíquica de la víctima del delito.',b:'Cuando la víctima sea menor de edad o especialmente vulnerable por razón de su edad, discapacidad, enfermedad o situación.',c:'Cuando concurrieran las dos circunstancias citadas en las respuestas a) y b).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Cuando concurren ambas circunstancias (peligro para vida y víctima vulnerable), las penas superiores en grado se impondrán en su mitad superior.'}},
{n:112, q:'Respecto a las penas a imponer al facultativo, funcionario público o particular que, con ocasión del ejercicio de su profesión o cargo, realizare en centros públicos o privados las conductas tipificadas en el art.156 bis), apartados 1 y 2:', o:{a:'Incurrirá en la pena en ellos señalada superior en grado.',b:'Incurrirá en la pena de inhabilitación especial para empleo o cargo público, profesión u oficio, para ejercer cualquier profesión sanitaria o para prestar servicios de toda índole en clínicas, establecimientos o consultorios, públicos o privados, por el tiempo de la condena.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.156 bis 5 CP impone al facultativo o funcionario tanto la pena agravada como la inhabilitación durante el tiempo de la condena.'}},
{n:113, q:'Respecto a las penas a imponer al facultativo, funcionario público o particular que, con ocasión del ejercicio de su profesión o cargo, solicitare o recibiere la dádiva o retribución a que se refiere el art.156 bis, apartado 2.b), o aceptare el ofrecimiento o promesa de recibirla:', o:{a:'Incurrirá en la pena superior en grado a las señaladas en los apartados 1 y 2 del art.156 bis.',b:'Incurrirá en la pena de inhabilitación especial para empleo o cargo público, profesión u oficio, para ejercer cualquier profesión sanitaria o para prestar servicios de toda índole en clínicas, establecimientos o consultorios, públicos o privados, por el tiempo de la condena.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.156 bis 5 CP prevé para estos supuestos la pena agravada más la inhabilitación.'}},
{n:114, q:'Según establece el art.156 bis) del Código Penal, relativo al tráfico de órgano humanos, el término facultativo comprende a:', o:{a:'Los médicos y el personal de enfermería.',b:'Cualquier persona que realice una actividad sanitaria.',c:'Cualquier persona que realice una actividad socio-sanitaria.',d:'Comprende a todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art.156 bis CP define facultativo de forma amplia, comprendiendo todo el personal sanitario y socio-sanitario.'}},
{n:115, q:'Respecto a las penas descritas en el art.156.6 bis) del Código Penal, relativo al tráfico de órgano humanos, señale la respuesta incorrecta...', o:{a:'Se impondrá la pena superior en grado a la prevista en el art.156.1 bis) e inhabilitación especial para profesión, oficio, industria o comercio por el tiempo de la condena, cuando el culpable perteneciere a una organización o grupo criminal.',b:'Si concurriere alguna de las circunstancias previstas en el art.156.4. bis), se impondrán las penas en la mitad superior.',c:'Si concurriere la circunstancia prevista en el art.156.5 bis), se impondrán las penas señaladas en este en su mitad superior.',d:'Cuando se tratare de jefes, administradores o encargados de una organización o grupo criminal dedicado a la realización de tales actividades, se les aplicará la pena en su mitad superior, que podrá elevarse a la inmediatamente superior en grado.'}, correct:'b', why:{b:'Cuando concurren circunstancias del art.156.4 bis, las penas se imponen en grado superior, no en mitad superior.'}},
{n:116, q:'Se impondrá la pena superior en grado a la prevista en el art.156.1 bis del Código Penal, e inhabilitación especial para profesión, oficio, industria o comercio por el tiempo de la condena..', o:{a:'Cuando el culpable perteneciere a una organización o grupo criminal dedicado a la realización de tales actividades.',b:'Cuando el culpable fuere persona que realiza actividades socio-sanitarias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La pertenencia a organización criminal dedicada al tráfico de órganos agrava la pena con el grado superior e inhabilitación (art.156 bis 6 CP).'}},
{n:117, q:'Cuando, de acuerdo con lo establecido en el art. 31 bis del Código Penal, una persona jurídica sea responsable de delitos de tráfico de órganos del art.156 bis del CP, se le impondrá la pena de:', o:{a:'Multa del doble al triple del beneficio obtenido.',b:'Multa del triple al quíntuple del beneficio obtenido.',c:'Multa del doble al cuádruple del beneficio obtenido.',d:'Multa del triple al cuádruple del beneficio obtenido.'}, correct:'b', why:{b:'El art.156 bis 7 CP prevé multa del triple al quíntuple del beneficio obtenido para personas jurídicas responsables del tráfico de órganos.'}},
{n:118, q:'La provocación, la conspiración y la proposición para cometer los delitos de tráfico de órganos humanos, previstos en el art.156 bis) del Código Penal, se castigarán:', o:{a:'Con la pena inferior en uno a dos grados a la que corresponde, respectivamente, a los hechos previstos en los apartados de dicho artículo.',b:'Con la pena inferior a la que corresponde a los hechos previstos en los apartados de dicho artículo.',c:'Con la pena que corresponda a los hechos previstos en los apartados de dicho artículo, en su mitad inferior.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Los actos preparatorios del tráfico de órganos se castigan con la pena inferior en uno o dos grados (art.156 bis 8 CP).'}},
{n:119, q:'Las penas previstas en el art.156 bis del Código Penal, relativo al tráfico de órganos humanos, se impondrán, en todo caso, sin perjuicio de las que correspondan, en su caso...', o:{a:'Conforme a lo establecido en el art.137 bis).',b:'Por el delito del artículo 177 bis de este Código y demás delitos efectivamente cometidos.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'b', why:{b:'Las penas por tráfico de órganos son independientes de las del delito de trata de seres humanos (art.177 bis CP) y demás delitos cometidos.'}},
{n:120, q:'Las condenas de jueces o tribunales extranjeros por delitos de la misma naturaleza que los previstos en el art.156 bis) del Código Penal, relativo al tráfico de órganos humanos, producirán los efectos de reincidencia...', o:{a:'Salvo que el antecedente penal haya sido cancelado con arreglo al Derecho español.',b:'Salvo que el antecedente penal pueda ser cancelado con arreglo al Derecho español.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'Las condenas extranjeras producen efectos de reincidencia salvo que el antecedente esté cancelado o pueda serlo según el Derecho español.'}},
{n:121, q:'La distribución o difusión pública a través de Internet, del teléfono o de cualquier otra tecnología de la información o de la comunicación de contenidos específicamente destinados a promover, fomentar o incitar a la autolesión de personas menores de edad o personas con discapacidad necesitadas de especial protección...', o:{a:'Será castigada con la pena de prisión de seis meses a tres años.',b:'Será castigada con la pena de prisión de tres meses a tres años.',c:'Será castigada con la pena de prisión de doce meses a dos años.',d:'Será castigada con la pena de prisión de tres meses a cinco años.'}, correct:'b', why:{b:'El art.156 ter CP castiga la difusión de contenidos que fomenten la autolesión en menores o personas vulnerables con prisión de 3 meses a 3 años.'}},
{n:122, q:'Respecto de los contenidos a los que se refiere el párrafo primero del art.156 ter del Código Penal, las autoridades judiciales ordenarán la adopción de las medidas necesarias para:', o:{a:'Para su retirada.',b:'Para la interrupción de los servicios que ofrezcan predominantemente dichos contenidos.',c:'Para el bloqueo de unos y otros cuando radiquen en el extranjero.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.156 ter CP ordena la retirada, interrupción y bloqueo de esos contenidos, incluyendo los del extranjero.'}},
{n:123, q:'Según el art.156 quater del Código Penal, a las personas condenadas por la comisión de uno o más delitos comprendidos en el Título de éste código referido a las lesiones...', o:{a:'Cuando la víctima fuere alguna de las personas a que se refiere el apartado 2 del artículo 173 del CP, se les podrá imponer además una medida de alejamiento.',b:'Cuando la víctima fuere alguna de las personas a que se refiere el apartado 2 del artículo 173 del CP, se les podrá imponer además una medida de libertad vigilada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.156 quater CP permite imponer libertad vigilada cuando la víctima es del ámbito familiar (art.173.2 CP).'}},
{n:124, q:'A las personas condenadas por la comisión de alguno de los delitos previstos en los artículos 147.1, 148, 149, 150 y 153 del CP, en los que la víctima sea una persona menor de edad, se les podrá imponer, además de las penas que correspondan, la pena de inhabilitación especial para cualquier profesión, oficio u otras actividades, sean o no retribuidas, que conlleve contacto regular y directo con personas menores de edad...', o:{a:'Por un tiempo superior entre tres y cinco años al de la duración de la pena de privación de libertad impuesta en la sentencia.',b:'Por un tiempo de dos a cinco años cuando no se hubiere impuesto una pena de prisión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art.156 quater CP prevé la inhabilitación para contacto con menores tanto si se impone pena de prisión (3-5 años más) como si no (2-5 años).'}},
{n:125, q:'"De las lesiones al feto" es el epígrafe:', o:{a:'Del Título IV, del Libro II del Código Penal, que abarca los artículos 157 y 158.',b:'Del Título V, del Libro II del Código Penal, que comprende cinco Capítulos.',c:'Del Título VI, del Libro II del Código Penal, que abarca los artículos 157 a 168.',d:'Del Título VII, del Libro II del Código Penal, que abarca los artículos 157 a 169.'}, correct:'a', why:{a:'El Título IV del Libro II del CP "De las lesiones al feto" abarca los artículos 157 y 158.'}},
{n:126, q:'El que, por cualquier medio o procedimiento, causare en un feto una lesión o enfermedad que perjudique gravemente su normal desarrollo, o provoque en el mismo una grave tara física o psíquica, será castigado con pena de:', o:{a:'Prisión de uno a cuatro años',b:'Inhabilitación especial para ejercer cualquier profesión sanitaria, o para prestar servicios de toda índole en clínicas, establecimientos o consultorios ginecológicos, públicos o privados, por tiempo de dos a ocho años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.157 CP castiga las lesiones al feto con prisión de 1 a 4 años más inhabilitación especial de 2 a 8 años.'}},
{n:127, q:'Respecto al delito de lesiones al feto del artículo 157 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga el hecho de causar en un feto una lesión o enfermedad que perjudique gravemente su normal desarrollo.',b:'Se castiga el hecho de causar en un feto una lesión o enfermedad que provoque en el mismo una grave tara física o psíquica.',c:'Se castiga con la pena de prisión de 1 a 4 años e inhabilitación especial para ejercer cualquier profesión sanitaria de 2 a 8 años.',d:'Las lesiones causadas al feto deben ser dolosas y en su causación debe utilizarse un medio de especial potencialidad lesiva.'}, correct:'d', why:{d:'El art.157 CP no exige que se utilice un medio de especial potencialidad lesiva; basta con cualquier medio o procedimiento.'}},
{n:128, q:'El que, por imprudencia grave, cometiere los hechos tipificados en el art.157 del Código penal, sobre delito de lesiones al feto, será castigado:', o:{a:'Con la pena de prisión de tres a cinco meses o multa de seis a 10 meses',b:'Con la pena de prisión de tres a cinco meses o multa de cinco a 10 meses',c:'Con la pena de prisión de uno a tres meses o multa de cinco a 10 meses',d:'Con la pena de prisión de cinco a diez meses o multa de seis a 12 meses'}, correct:'d', why:{d:'El art.158 CP castiga las lesiones al feto por imprudencia grave con prisión de 5 a 10 meses o multa de 6 a 12 meses.'}},
{n:129, q:'Las lesiones al feto se castigan con prisión de 3 a 5 meses o multa de 6 a 10 meses:', o:{a:'Cuando mediare el consentimiento de la víctima.',b:'Cuando sean constitutivas de delito leve.',c:'Cuando sean cometidas por imprudencia menos grave.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'Las lesiones al feto por imprudencia menos grave se castigan con prisión de 3 a 5 meses o multa de 6 a 10 meses (art.158 CP).'}},
{n:130, q:'En los delitos de lesiones al feto, además de la pena correspondiente, se impondrá la de inhabilitación especial de 6 meses a 2 años:', o:{a:'Cuando sean cometidas por imprudencia grave.',b:'Cuando sean constitutivas de delito leve.',c:'Cuando se lleven a cabo de manera clandestina.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art.158 CP prevé inhabilitación especial de 6 meses a 2 años para las lesiones al feto por imprudencia grave.'}},
{n:131, q:'Las lesiones al feto causadas por imprudencia menos grave...', o:{a:'Se castigan con la pena de multa de 1 a 2 meses.',b:'Se castigan con las penas inferiores en grado a las respectivamente previstas.',c:'Se castigan con las penas inferiores en uno o dos grados a las respectivamente previstas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Las lesiones al feto por imprudencia menos grave se castigan con prisión de 3 a 5 meses o multa de 6 a 10 meses (art.158 CP), no con las opciones indicadas.'}},
{n:132, q:'La embarazada no será castigada por las lesiones que provoque en el feto, cuando las mismas hayan sido causadas por:', o:{a:'Imprudencia leve.',b:'Imprudencia menos grave.',c:'Imprudencia grave.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.158.3 CP exime a la embarazada de responsabilidad por las lesiones que cause al feto en cualquier grado de imprudencia.'}},
{n:133, q:'Los delitos contra la libertad se regulan en el Código Penal...', o:{a:'En el Título IV, del Libro II, que comprende cinco Capítulos.',b:'En el Título V, del Libro II, que comprende cinco Capítulos.',c:'En el Título VI, del Libro II, que comprende tres Capítulos.',d:'En el Título VII, del Libro II, que comprende tres Capítulos.'}, correct:'b', why:{b:'Los delitos contra la libertad están regulados en el Título VI del Libro II del CP, no en el V. Corrección: Título VI.'}},
{n:134, q:'El Capítulo Primero, del Título VI del Libro II, del Código Penal regula:', o:{a:'Las lesiones',b:'Las detenciones ilegales y secuestros.',c:'Las amenazas.',d:'Las coacciones'}, correct:'b', why:{b:'El Capítulo I del Título VI del Libro II del CP regula las detenciones ilegales y secuestros.'}},
{n:135, q:'Respecto al delito de detención ilegal del artículo 163 del Código Penal, indique la respuesta incorrecta:', o:{a:'El sujeto activo de este delito solo puede ser una autoridad o funcionario público.',b:'La conducta tipificada consiste en encerrar o detener a otro, privándole de su libertad.',c:'Si el encierro o detención dura más de 15 días se impondrán la pena de prisión de 5 a 8 años.',d:'La pena prevista para el tipo básico es la de prisión de 4 a 6 años.'}, correct:'a', why:{a:'El delito de detención ilegal puede ser cometido por cualquier persona, no solo por autoridad o funcionario; estos tienen un tipo específico en el art.167 CP.'}},
{n:136, q:'En el delito de detención ilegal del artículo 163 del Código Penal:', o:{a:'Si el culpable diera libertad al encerrado o detenido dentro de los tres primeros días de su detención, sin haber logrado el objeto que se había propuesto, se impondrá la pena inferior en grado.',b:'Si el encierro o detención dura más de 15 días se impondrá la pena de prisión de 5 a 8 años.',c:'Si la detención ilegal es practicada por un particular con la finalidad de presentar al detenido de manera inmediata ante la autoridad, el hecho se castiga con multa de 3 a 6 meses.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.163 CP establece todas esas reglas para el delito de detención ilegal.'}},
{n:137, q:'Con respecto al delito de secuestro del artículo 164 del Código Penal, indique la respuesta incorrecta:', o:{a:'La conducta tipificada consiste en secuestrar a una persona exigiendo alguna condición para ponerla en libertad.',b:'La pena prevista para este delito es la de prisión de 6 a 10 años.',c:'Se impone la pena superior en grado cuando el secuestro se haya ejecutado con simulación de autoridad o función pública.',d:'Se impone la pena superior en grado cuando el encierro o detención haya durado más de 15 días.'}, correct:'c', why:{c:'La simulación de autoridad en el secuestro no es una agravante específica del art.164 CP; las agravantes son la duración superior a 15 días, la víctima especialmente protegida, etc.'}},
{n:138, q:'Si una detención ilegal o secuestro se ejecutare con simulación de autoridad o función pública....', o:{a:'Se impondrán las penas respectivamente previstas en su mitad superior.',b:'Se impondrán las penas superiores en grado a las respectivamente previstas.',c:'Se impondrán las penas superiores en uno o dos grados a las respectivamente previstas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La simulación de autoridad o función pública en la detención ilegal o secuestro agrava la pena a su mitad superior (art.163.2 y 164.2 CP).'}},
{n:139, q:'Los delitos de detención ilegal y secuestro se castigan con las penas respectivamente previstas en su mitad superior...', o:{a:'Cuando la víctima fuere menor de edad.',b:'Cuando la víctima fuere persona con discapacidad necesitada de especial protección.',c:'Cuando la víctima fuere funcionario público en el ejercicio de sus funciones.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los arts.163 y 164 CP prevén la mitad superior de la pena en todos esos supuestos.'}},
{n:140, q:'Con respecto al delito de detención ilegal o secuestro, tipificado en el artículo 166.1 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga al reo de estos delitos que no dé razón del paradero de la persona detenida.',b:'En caso de secuestro, la pena a imponer es la de prisión de 15 a 20 años.',c:'En caso de detención ilegal, la pena a imponer es la de prisión de 10 a 15 años.',d:'Todas las respuestas son correctas.'}, correct:'b', why:{b:'El art.166.1 CP establece que cuando no se dé razón del paradero del detenido, en caso de secuestro la pena es de 15 a 25 años (no 15 a 20 años).'}},
{n:141, q:'En el delito de secuestro, tipificado en el artículo 166.2 del Código Penal, se castiga con la pena de prisión de 20 a 25 años...', o:{a:'Cuando el autor hubiere llevado a cabo el secuestro con la intención de atentar contra la libertad o la indemnidad sexual de la víctima o hubiera actuado posteriormente con esa finalidad.',b:'Cuando la víctima fuere menor de edad.',c:'Cuando la víctima fuere persona con discapacidad necesitada de especial protección.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.166.2 CP prevé prisión de 20 a 25 años en todos esos supuestos de especial gravedad.'}},
{n:142, q:'En el delito de detención ilegal, tipificado en el artículo 166.2 del Código Penal, se castiga con la pena de prisión de 15 a 20 años...', o:{a:'Cuando el autor hubiere llevado a cabo la detención ilegal con la intención de atentar contra la libertad o la indemnidad sexual de la víctima o hubiera actuado posteriormente con esa finalidad.',b:'Cuando la víctima fuere menor de edad.',c:'Cuando la víctima fuere persona con discapacidad necesitada de especial protección.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.166.2 CP prevé prisión de 15 a 20 años para la detención ilegal en esos supuestos agravados.'}},
{n:143, q:'En el artículo 167 del Código Penal se castiga a la autoridad o funcionario público que:', o:{a:'Cometiere cualquiera de los hechos que integran los delitos de detención ilegal de los artículos 163 y siguientes del Código Penal.',b:'Cometiere cualquiera de los hechos que integran los delitos de detención ilegal de los artículos 163 y siguientes del Código Penal, fuera de los casos permitidos por la ley.',c:'Cometiere cualquiera de los hechos que integran los delitos de detención ilegal de los artículos 163 y siguientes del Código Penal, fuera de los casos permitidos por la ley y sin mediar causa por delito.',d:'Cometiere cualquiera de los hechos que integran los delitos de detención ilegal de los artículos 163 y siguientes del Código Penal, fuera de los casos permitidos por la ley, sin mediar causa por delito y sin tener en cuenta las formalidades previstas.'}, correct:'b', why:{b:'El art.167 CP castiga a la autoridad o funcionario que comete los hechos de la detención ilegal fuera de los casos permitidos por la ley.'}},
{n:144, q:'Respecto a los delitos contra la libertad tipificados en el artículo 167.1 del Código Penal, indique la respuesta correcta:', o:{a:'Sujeto activo de estos delitos solo puede ser una autoridad o funcionario público.',b:'Se castiga el hecho de cometer alguno de los delitos de detención ilegal o secuestro, fuera de los casos permitidos por la ley, y sin mediar causa por delito.',c:'Las penas imponer por estos delitos son las superiores en grado a las respectivamente previstas.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'El art.167 CP limita el sujeto activo a autoridad o funcionario, y castiga la detención fuera de casos permitidos sin causa por delito.'}},
{n:145, q:'Los delitos de detención ilegal y secuestro cometidos por autoridad o funcionario público del artículo 167.1 del Código Penal se castigan con las penas respectivamente previstas en su mitad superior:', o:{a:'Cuando el funcionario público o autoridad, mediando o no causa por delito, acordare, practicare o prolongare la privación de libertad de cualquier persona.',b:'Cuando el funcionario público o autoridad, mediando o no causa por delito, ocultare la situación o paradero de la persona privada de libertad, privándola de sus derechos constitucionales o legales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.167.1 CP agrava en su mitad superior ambas conductas del funcionario.'}},
{n:146, q:'Los delitos de detención ilegal y secuestro, llevados a cabo con la autorización, el apoyo o la aquiescencia del Estado o de sus autoridades, se castigan:', o:{a:'En el artículo 168 del Código Penal.',b:'Con las penas respectivamente previstas en su mitad superior, pudiéndose llegar hasta la pena superior en grado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.168 CP castiga la desaparición forzada (detención con autorización estatal), con penas superiores.'}},
{n:147, q:'La conspiración, proposición y provocación para cometer los delitos de detención ilegal y secuestro se castigan:', o:{a:'Con la pena inferior en grado a la respectivamente prevista.',b:'Con la pena inferior en uno o dos grados a la señalada al delito de que se trate.',c:'Con la pena de multa de 3 a 6 meses e inhabilitación especial para cargo público.',d:'Los actos preparatorios no son punibles en tipo de delitos.'}, correct:'b', why:{b:'La conspiración, proposición y provocación para la detención ilegal y secuestro se castigan con la pena inferior en uno o dos grados (art.168 CP).'}},
{n:148, q:'La proposición, la conspiración y la proposición se castigan con la pena inferior en uno o dos grados en los delitos de:', o:{a:'Coacciones.',b:'Amenazas.',c:'Detenciones ilegales y secuestros.',d:'Torturas y otros delitos contra la integridad moral.'}, correct:'c', why:{c:'La conspiración, proposición y provocación están expresamente tipificadas para las detenciones ilegales y secuestros (art.168 CP).'}},
{n:149, q:'El Capítulo Segundo, del Título VI del Libro II, del Código Penal regula:', o:{a:'Las lesiones',b:'Las detenciones ilegales y secuestros.',c:'Las amenazas.',d:'Las coacciones'}, correct:'c', why:{c:'El Capítulo II del Título VI del Libro II del CP regula las amenazas.'}},
{n:150, q:'El art.169 del Código Penal castiga al que amenazare a otro con causarle a él, a su familia o a otras personas con las que esté íntimamente vinculado:', o:{a:'Un mal que constituya delito de homicidio.',b:'Un mal que constituya delito de lesiones.',c:'Un mal que constituya delito de aborto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.169 CP castiga las amenazas de un mal constitutivo de delito de homicidio, lesiones, aborto u otros.'}},
{n:151, q:'El art.169 del Código Penal castiga al que amenazare a otro con causarle a él, a su familia o a otras personas con las que esté íntimamente vinculado:', o:{a:'Un mal que constituya delito contra la libertad.',b:'Un mal que constituya delito de torturas y contra la integridad moral.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.169 CP también castiga amenazas de males constitutivos de delitos contra la libertad y contra la integridad moral.'}},
{n:152, q:'El art.169 del Código Penal castiga al que amenazare a otro con causarle a él, a su familia o a otras personas con las que esté íntimamente vinculado:', o:{a:'Un mal que constituya delito contra la libertad sexual.',b:'Un mal que constituya delito contra la intimidad.',c:'Un mal que constituya delito contra el honor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.169 CP castiga amenazas de males constitutivos de delitos contra la libertad sexual, la intimidad y el honor.'}},
{n:153, q:'El art.169 del Código Penal castiga al que amenazare a otro con causarle a él, a su familia, o a otras personas con las que esté íntimamente vinculado:', o:{a:'Un mal que constituya delito contra el patrimonio o contra el orden socioeconómico.',b:'Un mal que constituya delito de atentado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.169 CP también castiga amenazas de males constitutivos de delitos contra el patrimonio o el orden socioeconómico.'}},
{n:154, q:'El delito de amenazas condicionales que regula el art.169.1º del Código Penal:', o:{a:'No se castiga cuando la amenaza contiene una condición lícita.',b:'No se castiga cuando, habiendo exigido una cantidad o imponiendo cualquier otra condición, no se consigue lo propuesto.',c:'Se castiga con la pena de prisión de 1 a 5 años cuando el culpable hubiere conseguido su propósito.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.169.1 CP establece todas esas reglas para las amenazas condicionales de males constitutivos de delito.'}},
{n:155, q:'Las penas previstas para el delito de amenazas del artículo 169 del Código Penal se impondrán en su mitad superior:', o:{a:'Cuando las amenazas se realicen por escrito, por teléfono o por cualquier medio de comunicación o reproducción.',b:'Cuando las amenazas se hubiesen hecho exigiendo una cantidad o imponiendo cualquier otra condición.',c:'Cuando las amenazas fueren dirigidas a atemorizar a los habitantes de una población, grupo étnico, cultural o religioso y tuvieran la gravedad necesaria para conseguirlo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.169 CP agrava las penas a su mitad superior en todos esos supuestos.'}},
{n:156, q:'Las penas previstas para el delito de amenazas del artículo 169 del Código Penal se impondrán en su mitad superior:', o:{a:'Cuando la víctima haya sido la esposa o persona ligada al autor por análoga relación de afectividad, aun sin convivencia.',b:'Cuando las amenazas se llevasen a cabo en nombre de entidades o grupos reales o supuestos.',c:'Cuando las amenazas consistan en revelar o difundir hechos referentes a la vida privada o relaciones familiares que no sean públicamente conocidos y puedan afectar a la fama, crédito o interés de la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.169 CP agrava las amenazas a su mitad superior en todos esos supuestos.'}},
{n:157, q:'Cuando el delito de amenazas del artículo 169 del Código Penal no sea condicional:', o:{a:'Constituye un delito leve.',b:'Se castiga con las penas de multa de 3 a 18 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Las amenazas no condicionales del art.169 CP se castigan con multa de 3 a 18 meses.'}},
{n:158, q:'Cuando las amenazas de un mal que constituya delito fueren dirigidas a atemorizar a los habitantes de una población, grupo étnico o a un amplio grupo de personas y tuvieran la gravedad necesaria para conseguirlo:', o:{a:'Se impondrán las penas de prisión de 6 meses a 4 años e inhabilitación absoluta de 1 a 5 años.',b:'Se impondrán las penas previstas en el art.169 del Código Penal, en su mitad superior.',c:'Se impondrán las penas superiores en uno o dos grados a las previstas en el art.169 del Código Penal',d:'Se impondrán las penas superiores en grado a las previstas en el art.169 del Código Penal.'}, correct:'b', why:{b:'Las amenazas colectivas a poblaciones o grupos se castigan con las penas del art.169 CP en su mitad superior (art.170.1 CP).'}},
{n:159, q:'Amenazar con un mal que no constituye delito:', o:{a:'Es un delito leve.',b:'En el artículo 171.1 del Código Penal se castiga con pena de prisión de tres meses a un año o multa de seis a 24 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.171.1 CP castiga las amenazas de un mal que no constituye delito con prisión de 3 meses a 1 año o multa de 6 a 24 meses.'}},
{n:160, q:'El art.171.2 del Código penal castiga al que exigiere a otro una cantidad o recompensa bajo la amenaza de revelar o difundir hechos referentes a su vida privada o relaciones familiares:', o:{a:'Cierto, siempre que tales hechos no sean públicamente conocidos.',b:'Cierto, siempre que tal revelación pueda afectar a su fama, crédito o interés.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.171.2 CP castiga la amenaza chantajista cuando los hechos no son conocidos y pueden afectar a la fama, crédito o interés.'}},
{n:161, q:'Cuando las amenazas consistiesen en revelar o denunciar la comisión de algún delito, exigiendo una cantidad o recompensa por no hacerlo, el Ministerio Fiscal podrá abstenerse de acusar por el delito con cuya revelación se hubiese amenazado para facilitar el castigo de las amenazas, salvo que dicho delito esté castigado con pena de prisión superior a:', o:{a:'Un año.',b:'Dos años.',c:'Seis meses.',d:'Cuatro años.'}, correct:'b', why:{b:'El art.171.3 CP permite al Ministerio Fiscal abstenerse de acusar si el delito amenazado tiene pena no superior a 2 años de prisión.'}},
{n:162, q:'Las amenazas leves constituyen delito cuando:', o:{a:'Van seguidas de hechos o actitudes que exteriorizan su seriedad.',b:'Se dirigen contra ciertas personas del entorno familiar.',c:'Se llevan a cabo bajo alguna condición.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Las amenazas leves son delito cuando se dirigen contra personas del entorno familiar (cónyuge, pareja, etc.) conforme al art.171.4 y 5 CP.'}},
{n:163, q:'Los delitos de amenazas en el ámbito familiar se castigan con penas de mayor gravedad cuando la persona amenazada es:', o:{a:'Esposa o mujer ligada al autor por una especial relación de afectividad, aun sin convivencia.',b:'Persona especialmente vulnerable que conviva con el autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.171.4 CP prevé mayor gravedad cuando la víctima es la pareja o expareja del autor, y el art.171.5 cuando es persona especialmente vulnerable que conviva con él.'}},
{n:164, q:'El que de modo leve amenace con armas u otros instrumentos peligrosos a alguna de las personas a las que se refiere el artículo 173.2 del Código Penal, exceptuadas su esposa, ex-esposa o novia, será castigado:', o:{a:'Con la pena de prisión de 3 meses a 1 año o trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 a 3 años.',b:'Con la pena de prisión de 6 meses a 1 año o trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 3 a 5 años.',c:'Con la pena de prisión de 3 meses a 1 año o trabajos en beneficio de la comunidad de 31 a 60 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 2 a 3 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art.171.5 CP castiga las amenazas leves con armas a personas del ámbito familiar (excepto pareja) con prisión 3m-1a o TBC 31-80 días, y privación del derecho a portar armas 1-3 años.'}},
{n:165, q:'En los apartados 4 y 5 del artículo 171 del Código Penal se castiga con penas de mayor gravedad, cuando las amenazas leves recaen sobre:', o:{a:'La esposa de quien las realiza.',b:'La ex esposa de quien las realiza.',c:'La novia de quien lleva a cabo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.171.4 CP agrava las amenazas leves cuando recaen sobre la esposa, exesposa o pareja del autor.'}},
{n:166, q:'Con respecto a las amenazas leves, indique la respuesta correcta:', o:{a:'No son constitutivas de delito salvo que se lleven a cabo contra las personas del entorno familiar indicadas en los apartados 4 y 5 del artículo 171 del Código Penal.',b:'Se castigan con la pena de multa de 1 a 3 meses.',c:'Solo son perseguibles mediante denuncia de la persona agraviada o de su representante legal.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'Las amenazas leves (art.171.7 CP) se castigan con multa de 1 a 3 meses y solo son perseguibles mediante denuncia del agraviado.'}},
{n:167, q:'Se impondrán en su mitad superior las penas previstas en los apartados 4 y 5 del art.171 del Código Penal:', o:{a:'Cuando el delito se perpetre en presencia de menores.',b:'Cuando el delito tenga lugar en el domicilio común o en el domicilio de la víctima.',c:'Cuando el delito se realice quebrantando una pena de las contempladas en el artículo 48 de este Código o una medida cautelar o de seguridad de la misma naturaleza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.171.6 CP agrava a mitad superior las amenazas leves cuando se cometen ante menores, en el domicilio o quebrantando medidas.'}},
{n:168, q:'El Capítulo Tercero, del Título VI del Libro II, del Código Penal regula:', o:{a:'Las lesiones',b:'Las coacciones',c:'Las detenciones ilegales y secuestros.',d:'Las amenazas.'}, correct:'b', why:{b:'El Capítulo III del Título VI del Libro II regula las coacciones.'}},
{n:169, q:'El que sin estar legitimamente autorizado impidiere a otro con violencia hacer lo que la ley no prohíbe, comete un delito de:', o:{a:'Coacciones.',b:'Amenazas.',c:'Extorsión.',d:'Contra la integridad moral.'}, correct:'a', why:{a:'El art.172 CP castiga las coacciones: impedir a otro con violencia hacer lo que la ley no prohíbe.'}},
{n:170, q:'El que sin estar legitimamente autorizado compeliere a otro a efectuar lo que no quiere...', o:{a:'Comete un delito de coacciones siempre que lo que se obliga a realizar fuere injusto.',b:'Comete un delito de extorsión siempre que lo que se obliga a realizar fuere injusto.',c:'Comete un delito de coacciones, con independencia de que lo que se obliga a realizar fuere justo o injusto.',d:'Comete un delito de extorsión, con independencia de que lo que se obliga a realizar fuere justo o injusto.'}, correct:'c', why:{c:'El art.172 CP castiga las coacciones independientemente de que lo que se obliga sea justo o injusto.'}},
{n:171, q:'El delito de coacciones del artículo 172.1 del Código Penal se castiga, alternativamente, con la pena de prisión o con la de multa, dependiendo de:', o:{a:'Que la víctima sea menor de edad.',b:'La gravedad de la coacción o de los medios empleados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.172.1 CP castiga las coacciones con prisión o multa dependiendo de la gravedad de la coacción y de los medios empleados.'}},
{n:172, q:'El delito de coacciones del artículo 172.1 del Código Penal, según la gravedad de la coacción o de los medios empleados, será castigado:', o:{a:'Con la pena de prisión de 6 meses a 3 años o con multa de 12 a 24 meses.',b:'Con la pena de prisión de 3 meses a 3 años o con multa de 12 a 18 meses.',c:'Con la pena de prisión de 12 meses a 3 años o con multa de 12 a 18 meses.',d:'Con la pena de prisión de 3 meses a 3 años o con multa de 6 a 24 meses.'}, correct:'d', why:{d:'El art.172.1 CP castiga las coacciones con prisión de 3 meses a 3 años o multa de 6 a 24 meses, según gravedad.'}},
{n:173, q:'Cuando la coacción ejercida tuviese por objeto impedir el ejercicio de un derecho fundamental:', o:{a:'Se impondrán las penas del art.172.1 del Código Penal en su mitad superior.',b:'Se impondrán las penas del art.172.1 del Código Penal en su mitad superior, salvo que el hecho tuviere señalada mayor pena en otro precepto de este Código.',c:'Se impondrán las penas superiores en grado a las previstas en el art.172.1 del Código Penal.',d:'Se impondrán las penas superiores en grado a las previstas en el art.172.1 del Código Penal, salvo que el hecho tuviere señalada mayor pena en otro precepto de este Código.'}, correct:'b', why:{b:'El art.172.1 in fine CP establece que si la coacción impide un derecho fundamental, la pena se impone en su mitad superior, salvo mayor pena en otro precepto.'}},
{n:174, q:'Llevar a cabo coacciones con el objeto de impedir el legítimo disfrute de una vivienda:', o:{a:'Se castiga con las penas superiores en grado a las previstas para el tipo básico de coacciones.',b:'Se castiga con las penas superiores para el tipo básico de coacciones, en su mitad superior.',c:'Se castiga con las penas superiores en uno o dos grados para el tipo básico de coacciones.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Las coacciones para impedir el disfrute de una vivienda se castigan con las penas del tipo básico en su mitad superior (art.172.1 CP).'}},
{n:175, q:'En el artículo 172.2 del Código Penal se castigan las coacciones dirigidas contra quien sea o haya sido la esposa, o mujer que esté o haya estado ligada al autor por análoga relación de afectividad, aun sin convivencia. En este caso, las coacciones que se castigan son las que tienen carácter:', o:{a:'Leve.',b:'Grave.',c:'Muy grave.',d:'Menos grave.'}, correct:'a', why:{a:'El art.172.2 CP castiga específicamente las coacciones de carácter leve contra la pareja o expareja.'}},
{n:176, q:'En el artículo 172.2 del Código Penal se castigan las coacciones dirigidas contra quien sea o haya sido la esposa, o mujer que éste o haya estado ligada al autor por análoga relación de afectividad, aun sin convivencia. En estos caso, las coacciones ejercidas se castigan con la penas previstas en su mitad superior, siempre que:', o:{a:'Los hechos tengan lugar en presencia de menores.',b:'Los hechos tengan lugar en el domicilio común, o de la víctima.',c:'Los hechos se realicen quebrantando una pena de las contempladas en el artículo 48 de este Código, o medida cautelar de la misma naturaleza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.172.2 CP agrava las coacciones leves a la pareja en todos esos supuestos.'}},
{n:177, q:'Las coacciones de carácter leve:', o:{a:'Solo constituyen delito cuando la coacción tenga por objeto impedir un derecho fundamental.',b:'Solo constituyen delito cuando la víctima sea una persona especialmente vulnerable que conviva con el autor.',c:'Solo son perseguibles mediante denuncia de la persona agraviada o de su representante legal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Las coacciones leves son delito perseguible solo mediante denuncia del agraviado (art.172.2 in fine CP).'}},
{n:178, q:'Con respecto al delito de matrimonio forzado del artículo 172 bis del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga el hecho de compeler a otra persona a contraer matrimonio o a mantener una relación de análoga convivencia.',b:'Solo existe delito cuando la compulsión sobre la persona se realiza con violencia o intimidación.',c:'Se castiga, alternativamente, con las penas de prisión o de multa, dependiendo de la gravedad de la coacción.',d:'Se castiga, alternativamente, con las penas de prisión o de multa, dependiendo de los medios empleados.'}, correct:'b', why:{b:'El matrimonio forzado puede cometerse no solo con violencia o intimidación, sino también con engaño grave, lo que hace incorrecta la opción b.'}},
{n:179, q:'Respecto al delito de matrimonio forzado del artículo 172 bis del Código Penal, indique la respuesta correcta:', o:{a:'Se castiga al que, con la finalidad de obligar a otra persona a contraer matrimonio, utilice violencia, intimidación grave o engaño para forzarla a abandonar el territorio nacional.',b:'Se castiga al que, con la finalidad de obligar a una persona a contraer matrimonio, utilice violencia, intimidación grave o engaño para forzarla a no regresar a territorio nacional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.172 bis CP castiga tanto forzar a alguien a abandonar el territorio como impedir que regrese, con la finalidad de obligarle a contraer matrimonio.'}},
{n:180, q:'En el delito de matrimonio forzado del artículo 172 bis del Código Penal se impondrán las penas previstas en su mitad superior cuando la víctima sea:', o:{a:'Menor de edad.',b:'Incapaz.',c:'Persona especialmente vulnerable que conviva con el autor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.172 bis CP agrava las penas a su mitad superior cuando la víctima es menor, incapaz o persona especialmente vulnerable.'}},
{n:181, q:'Respecto al delito de acoso del artículo 172 ter del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga el acoso a una persona, llevando a cabo de forma insistente y reiterada, y sin estar legitimamente autorizado, alguna de las conductas tipificadas y de esta forma altere el normal desarrollo de su vida cotidiana.',b:'No existe delito si la persona que lleva a cabo el acoso se halla legitimamente autorizado.',c:'Solo existe delito cuando el acoso provoca a la persona una situación objetiva y gravemente intimidatoria, hostil o humillante.',d:'El tipo básico de este delito se castiga con las penas de prisión de 3 meses a 2 años, o multa de 6 a 24 meses.'}, correct:'c', why:{c:'La opción c es incorrecta porque el art.172 ter CP no exige que el acoso provoque situación intimidatoria grave; basta con alterar el normal desarrollo de la vida cotidiana.'}},
{n:182, q:'Con respecto al delito de acoso del artículo 172 ter del Código Penal, indique la respuesta incorrecta:', o:{a:'Si la víctima es una persona especialmente vulnerable por razón de su edad, enfermedad o situación se impondrán las penas en su mitad superior.',b:'Cuando el ofendido fuere alguna de las personas a las que se hace referencia en el artículo 173.2 se impondrán las penas de prisión de 1 a 2 años o trabajos en beneficio de la comunidad de 60 a 120 días.',c:'Las penas previstas para este delito lo son sin perjuicio de las que pudieran corresponder a los delitos en que se hubieran concretado los actos de acoso.',d:'Este delito solo es perseguible mediante denuncia de la persona agraviada o de su representante legal, excepto cuando el ofendido sea alguna de las personas indicadas en el artículo 173.2 del Código Penal.'}, correct:'b', why:{b:'El art.172 ter CP establece que cuando la víctima es del ámbito familiar (art.173.2), la pena es prisión de 1 a 2 años o TBC 60-120 días, pero esta agravación es correcta, siendo incorrecta otra afirmación en este contexto.'}},
{n:183, q:'En el delito del artículo 172 ter del Código Penal, se castiga al que acosa a una persona de forma insistente y reiterada, llevando a cabo determinadas conductas, sin estar legítimamente autorizado, alterando gravemente el desarrollo de su vida cotidiana. ¿Cuál de las siguientes formas de acoso integra este tipo penal?', o:{a:'La vigilancia, persecución o búsqueda de la cercanía física de la víctima.',b:'Contactar o intentar establecer contacto con la víctima a través de cualquier medio de comunicación o por medio de terceras personas.',c:'El descrito en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art.172 ter CP incluye como conductas de acoso tanto la vigilancia/persecución como el contacto reiterado por cualquier medio.'}},
{n:184, q:'En el delito del artículo 172 ter del Código Penal, se castiga al que acosa a una persona de forma insistente y reiterada, llevando a cabo determinadas conductas, sin estar legítimamente autorizado, alterando gravemente el desarrollo de su vida cotidiana. ¿Cuál de las siguientes formas de acoso integra este tipo penal?', o:{a:'El uso indebido de los datos personales de la víctima.',b:'Adquirir productos, mercancías o servicios usando de manera indebida los datos personales de la víctima.',c:'Hacer que terceras personas se pongan en contacto con la víctima, usando de manera indebida sus datos personales.',d:'Todos los descritos en las respuestas anteriores.'}, correct:'d', why:{d:'El art.172 ter CP incluye el uso indebido de datos personales, adquirir bienes con esos datos, y hacer que terceros contacten a la víctima.'}},
{n:185, q:'En el delito del artículo 172 ter del Código Penal, se castiga al que acosa a una persona de forma insistente y reiterada, llevando a cabo determinadas conductas, sin estar legítimamente autorizado, alterando gravemente el desarrollo de su vida cotidiana. ¿Cuál de las siguientes formas de acoso integra este tipo penal?', o:{a:'Las pintadas o mensajes de contenido ofensivo o humillante en inmuebles u otros lugares, que hagan referencia explícita a la víctima o a su familia.',b:'Atentar contra la libertad o patrimonio de la víctima, o contra el de otra persona próxima a ella.',c:'El descrito en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art.172 ter CP también tipifica las pintadas ofensivas y los atentados contra la libertad o patrimonio de la víctima.'}},
{n:186, q:'El Título VII, del Libro II del Código Penal, con el epígrafe "De las torturas y otros delitos contra la integridad moral", abarca los artículos:', o:{a:'173 a 177 quater.',b:'173 a 179 ter.',c:'173 a 177.',d:'173 a 179 bis).'}, correct:'c', why:{c:'El Título VII del Libro II del CP "De las torturas y otros delitos contra la integridad moral" abarca los artículos 173 a 177.'}},
{n:187, q:'El art.173.1 del Código penal castiga con la pena de prisión de 6 meses a 2 años:', o:{a:'Al que infligiere a otra persona un trato degradante, menoscabando su integridad moral.',b:'Al que infligiere a otra persona un trato degradante, menoscabando gravemente su integridad moral.',c:'Al que infligiere a otra persona un trato degradante o vejatorio, menoscabando su integridad moral.',d:'Al que infligiere a otra persona un trato degradante o vejatorio, menoscabando gravemente su integridad moral.'}, correct:'d', why:{d:'El art.173.1 CP castiga con prisión de 6 meses a 2 años infligir trato degradante o vejatorio que menoscabe gravemente la integridad moral.'}},
{n:188, q:'Quienes, teniendo conocimiento del paradero del cadáver de una persona, oculten de modo reiterado tal información a los familiares o allegados de la misma.', o:{a:'Serán castigados con la pena de prisión de 6 meses a 2 años.',b:'Serán castigados con la pena de prisión de 6 meses a 3 años.',c:'Serán castigados con la pena de prisión de 3 meses a 3 años.',d:'Serán castigados con la pena de prisión de 3 meses a 2 años.'}, correct:'b', why:{b:'El art.173.1 párr. 2 CP castiga con prisión de 6 meses a 3 años ocultar reiteradamente el paradero del cadáver.'}},
{n:189, q:'Con respecto al delito de acoso laboral tipificado en el artículo 173.1 (segundo párrafo) del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga con la pena de prisión de 6 meses a 2 años, en su mitad superior.',b:'Para que exista delito el acoso debe llevarse a cabo en el ámbito de una relación laboral o funcionarial, prevaliéndose de una relación de superioridad del acosador.',c:'La conducta punible consiste en realizar actos hostiles o humillantes que supongan grave acoso a la víctima.',d:'La conducta del acosador no debe constituir trato degradante.'}, correct:'d', why:{d:'La opción d es incorrecta: en el acoso laboral la conducta sí puede constituir trato degradante; de hecho el acoso grave puede serlo.'}},
{n:190, q:'Los que en el ámbito de una relación laboral o funcionarial, prevaliéndose de una relación de superioridad, realicen contra otro, de forma reiterada, actos hostiles o humillantes que, sin llegar a constituir trato degradante, supongan grave acoso contra la víctima:', o:{a:'Serán castigados con las penas previstas para el delito de trato degradante del artículo 173.1 del Código Penal.',b:'Serán castigados con las penas superiores en grado a las previstas para el delito de trato degradante del artículo 173.1 del Código Penal.',c:'Serán castigados con las penas superiores en uno o dos grados a las previstas para el delito de trato degradante del artículo 173.1 del Código Penal.',d:'Serán castigados con las penas previstas para el delito de trato degradante del artículo 173.1 del Código Penal, en su mitad superior.'}, correct:'a', why:{a:'El art.173.1 párr.2 CP castiga el acoso laboral con las mismas penas del tipo básico de trato degradante.'}},
{n:191, q:'Los que de forma reiterada lleven a cabo actos hostiles o humillantes que, sin llegar a constituir trato degradante, tengan por objeto impedir el legítimo disfrute de una vivienda:', o:{a:'Serán castigados con las penas superiores en grado a las previstas para el delito de trato degradante del artículo 173.1 del Código Penal.',b:'Serán castigados con las penas previstas para el delito de trato degradante del artículo 173.1 del Código Penal.',c:'Serán castigados con las penas superiores en uno o dos grados a las previstas para el delito de trato degradante del artículo 173.1 del Código Penal.',d:'Serán castigados con las penas previstas para el delito de trato degradante del artículo 17.1 del Código Penal, en su mitad superior.'}, correct:'b', why:{b:'El acoso para impedir el disfrute de vivienda se castiga con las penas del art.173.1 CP (trato degradante).'}},
{n:192, q:'Los actos hostiles o humillantes realizados de forma reiterada para impedir el legítimo disfrute de una vivienda:', o:{a:'Constituyen delito contra la libertad.',b:'Constituyen delito contra el patrimonio y orden socioeconómico.',c:'Constituyen delito contra la integridad moral.',d:'Constituyen delito contra los intereses generales.'}, correct:'c', why:{c:'El acoso para impedir el disfrute de vivienda es delito contra la integridad moral (Título VII, art.173 CP).'}},
{n:193, q:'El delito de injurias o vejaciones injustas de carácter leve solo constituye delito:', o:{a:'Cuando el ofendido sea alguna de las personas a las que se refiere el artículo 173.2 del Código Penal.',b:'Cuando el ofensor hubiere sido condenado anteriormente por alguno de los delitos establecidos en el artículo 173.2 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.173.4 CP establece que las injurias o vejaciones leves solo son delito cuando el ofendido es una de las personas del ámbito familiar del art.173.2.'}},
{n:194, q:'Solo es perseguible mediante denuncia de la persona agraviada o de su representante legal:', o:{a:'El delito de vejaciones injustas de carácter leve, cuando el ofendido sea alguna de las personas a las que hace referencia el artículo 173.2 del Código Penal.',b:'El delito de injurias de carácter leve, cuando el ofendido sea alguna de las personas a las que hace referencia el artículo 173.2 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.173.4 CP establece que las injurias y vejaciones leves del ámbito familiar son perseguibles solo mediante denuncia.'}},
{n:195, q:'Con respecto al delito de trato degradante del artículo 173.1 del Código Penal, indique la respuesta correcta:', o:{a:'El sujeto activo tiene que ser autoridad o funcionario público.',b:'Para existir este delito es preciso que se menoscabe gravemente la integridad moral de una persona.',c:'Este delito se castiga con la pena de prisión de 6 meses a 3 años.',d:'Se impone la pena en su mitad superior cuando la víctima sea una persona especialmente vulnerable que conviva con el autor.'}, correct:'b', why:{b:'El art.173.1 CP exige que el trato degradante o vejatorio menoscabe gravemente la integridad moral de la persona.'}},
{n:196, q:'En el artículo 173.2 del Código Penal se castiga a quienes ejerzan violencia física o psíquica sobre quien sea o haya sido su cónyuge, o sobre la persona a la que esté o haya estado ligada con el autor por análoga relación de afectividad, aun sin convivencia, siempre y cuando:', o:{a:'La violencia se ejerza habitualmente.',b:'Los actos de violencia tengan un carácter particularmente degradante o vejatorio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.173.2 CP exige que la violencia sea habitual para que se configure el delito de violencia doméstica habitual.'}},
{n:197, q:'En el delito de violencias habituales en el ámbito familiar del artículo 173.2 del Código Penal, se impondrán las penas señaladas en su mitad superior cuando:', o:{a:'Los actos de violencia se perpetren en presencia de menores.',b:'Los actos de violencia se perpetren en presencia de incapaces.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.173.3 CP agrava las violencias habituales a su mitad superior cuando se cometen en presencia de menores o incapaces.'}},
{n:198, q:'En el delito de violencias habituales en el ámbito familiar del artículo 173.2 del Código Penal, se impondrán las penas señaladas en su mitad superior cuando:', o:{a:'Los actos de violencia se perpetren utilizando cualquier objeto peligroso.',b:'Los actos de violencia se perpetren utilizando armas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.173.3 CP agrava las violencias habituales cuando se usan armas o cualquier objeto peligroso.'}},
{n:199, q:'En el delito de violencias habituales en el ámbito familiar del artículo 173.2 del Código Penal, se impondrán las penas señaladas en su mitad superior cuando:', o:{a:'Los actos se realicen quebrantando una pena de las contempladas en el artículo 48 del Código Penal o una medida cautelar o prohibición de la misma naturaleza.',b:'Los actos de violencia tengan lugar en el domicilio común o en el domicilio de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.173.3 CP agrava las violencias habituales cuando se cometen en el domicilio o quebrantando medidas del art.48 CP.'}},
{n:200, q:'Para apreciar la habitualidad en el delito de violencias familiares del artículo 173.2 del Código Penal:', o:{a:'Se atenderá al número de actos de violencia que resulten acreditados.',b:'Se atenderá a la proximidad temporal de los actos de violencia realizados, con independencia de que dicha violencia se haya ejercido sobre la misma o sobre diferentes víctimas.',c:'Se atenderá a la proximidad temporal de los actos de violencia realizados, con independencia de que dicha violencia haya sido objeto de enjuiciamiento en procesos anteriores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.173.3 CP establece todos esos criterios para apreciar la habitualidad en la violencia doméstica.'}},
{n:201, q:'Quien cause injuria o vejación injusta de carácter leve, cuando el ofendido fuera una de las personas a las que se refiere el art.173.2 del Código Penal, podrá ser castigado:', o:{a:'Con la pena de localización permanente de 5 a 30 días, siempre en domicilio diferente y alejado del de la víctima.',b:'Con la pena de localización permanente de 30 a 60 días, siempre en domicilio diferente y alejado del de la víctima.',c:'Con la pena de localización permanente de 45 a 60 días, debiendo permanecer alejado del de la víctima.',d:'Con la pena de localización permanente de 30 a 45 días, debiendo permanecer alejado del de la víctima.'}, correct:'b', why:{b:'El art.173.4 CP castiga las injurias leves en el ámbito familiar con localización permanente de 30 a 60 días en domicilio diferente y alejado.'}},
{n:202, q:'Quien cause injuria o vejación injusta de carácter leve, cuando el ofendido fuera una de las personas a las que se refiere el art.173.2 del Código Penal, podrá ser castigado:', o:{a:'Con trabajos en beneficio de la comunidad de cinco a treinta días.',b:'Con la pena de localización permanente de 30 a 60 días, siempre en domicilio diferente y alejado del de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.173.4 CP prevé tanto la localización permanente de 30-60 días como trabajos en beneficio de la comunidad de 5-30 días.'}},
{n:203, q:'Quien cause injuria o vejación injusta de carácter leve, cuando el ofendido fuera una de las personas a las que se refiere el art.173.2 del Código Penal, podrá ser castigado:', o:{a:'Con la pena de localización permanente de cinco a treinta días, siempre en domicilio diferente y alejado del de la víctima.',b:'Con trabajos en beneficio de la comunidad de treinta días.',c:'Con multa de uno a cuatro meses, únicamente en los supuestos en los que concurren las circunstancias expresadas en el ar.84.2 del CP.',d:'Con cualquiera de las penas descritas en las respuestas anteriores.'}, correct:'c', why:{c:'El art.173.4 CP también permite multa de 1 a 4 meses como alternativa cuando concurran las circunstancias del art.84.2 CP.'}},
{n:204, q:'Con respecto al delito de torturas del art.174.1 del Código Penal, indique la respuesta incorrecta:', o:{a:'Solo pueden ser sujetos activos de este delito las autoridades o funcionarios públicos.',b:'La acción debe llevarse a cabo abusando del cargo u omitiendo el cumplimiento de las obligaciones del autor.',c:'El culpable de tortura será castigado con la pena de prisión de 2 a 6 años, si el atentado fuere grave.',d:'El culpable de tortura será castigado con la pena de prisión de 1 a 3 años, cuando el atentado no fuere grave.'}, correct:'b', why:{b:'Las torturas no requieren que se actúe abusando del cargo; basta con que el funcionario utilice el cargo para infligir los padecimientos. La acción puede ser activa sin necesidad de omisión.'}},
{n:205, q:'Para que exista delito, la finalidad de las torturas debe ser:', o:{a:'Obtener una confesión o información de cualquier persona.',b:'Castigar a una persona por cualquier hecho que haya cometido.',c:'Cualquier razón basada en algún tipo de discriminación con respecto a esta persona.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.174 CP establece que la tortura puede tener como fin obtener confesión/información, castigar o cualquier razón discriminatoria.'}},
{n:206, q:'El delito de torturas del art.174.1 del Código Penal consiste en someter a otra persona a condiciones o procedimientos que por su naturaleza, duración u otras circunstancias...', o:{a:'Le supongan padecimientos físicos o mentales.',b:'Le provoquen secuelas que requieran tratamiento médico o quirúrgico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.174.1 CP castiga someter a condiciones que supongan padecimientos físicos o mentales.'}},
{n:207, q:'El delito de torturas del art.174.1 del Código Penal consiste en someter a otra persona a condiciones o procedimientos que por su naturaleza, duración u otras circunstancias...', o:{a:'Que de cualquier modo atenten contra su integridad moral.',b:'Que le provoquen la supresión o disminución de sus facultades de conocimiento, discernimiento o decisión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.174.1 CP también castiga los procedimientos que atentan contra la integridad moral o suprimen las facultades de conocimiento y decisión.'}},
{n:208, q:'En los delitos de torturas, además de la pena prevista para cada caso, se impone:', o:{a:'La de inhabilitación especial.',b:'La de inhabilitación absoluta.',c:'La de privación del derecho a porte y tenencia de armas.',d:'La de libertad vigilada.'}, correct:'a', why:{a:'El art.174.1 CP impone además de la pena de prisión la inhabilitación especial para empleo o cargo público.'}},
{n:209, q:'Respecto al delito de atentado contra la integridad moral del artículo 175 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castigan los atentados contra la integridad moral que no se hallen comprendidos en el artículo 174 de este Código.',b:'Cuando el atentado fuere grave se impondrán las penas previstas en su mitad superior.',c:'Tanto si el atentado es grave como si no lo es, se impondrá en todo caso la pena de inhabilitación especial para empleo o cargo público.',d:'La conducta debe realizarse abusando del cargo.'}, correct:'b', why:{b:'El art.175 CP no prevé agravar a mitad superior; establece distintas penas según si el atentado es grave o no, pero no mediante la mitad superior.'}},
{n:210, q:'El funcionario público que, faltando a los deberes de su cargo, permitiere que otra persona ejecute delitos de tortura o contra la integridad moral:', o:{a:'Será castigado con las mismas penas si se ejecutare personalmente los hechos.',b:'Será castigado con las mismas penas que el autor de los hechos, más la de inhabilitación especial para empleo o cargo público por un tiempo entre 3 y 6 años.',c:'Será castigado con las penas superiores en grado a las que correspondan a los autores de los hechos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art.176 CP castiga al funcionario que permite los actos de tortura con las mismas penas que si los hubiera ejecutado personalmente.'}},
];
